import { MONTH_NAMES } from "../config";
import { cleanText, headersOf, IssueCollector, parseMonthIndex, parseNumber, resolveColumn } from "./normalize";
import { AgendaResult } from "./types";

type Row = Record<string, unknown>;

/**
 * Hoja CAPACIDADES_AGENDA: una fila por equipo y mes con las horas que la agenda del equipo
 * estuvo abierta ("Capacidad agenda"). De la hoja sólo se usa esa columna: el potencial
 * (horas de clínica abierta) sale de las hojas de horas hábiles, para tener un único denominador.
 * El tope de la agenda sobre el potencial se aplica en el cálculo, no acá.
 */
export const parseCapacidades = (rows: Row[]): AgendaResult => {
  const issues = new IssueCollector("AGENDA");
  const agenda: AgendaResult["agenda"] = {};
  const headers = headersOf(rows);

  const yearCol = resolveColumn(headers, ["Ano", "Año", "Anio", "Year"]);
  const monthCol = resolveColumn(headers, ["Mes"]);
  const equipCol = resolveColumn(headers, ["Equipo"]);
  const agendaCol = resolveColumn(headers, ["Capacidad agenda", "Capacidad de agenda", "Horas agenda"]);
  const missing = [
    yearCol ? "" : "Año", monthCol ? "" : "Mes", equipCol ? "" : "Equipo", agendaCol ? "" : "Capacidad agenda",
  ].filter((x) => x !== "");
  if (!yearCol || !monthCol || !equipCol || !agendaCol) {
    issues.add("agenda-missing-columns", "error", "Faltan columnas en la hoja de capacidad de agenda.", missing.join(", "));
    return { agenda, issues: issues.toArray() };
  }

  rows.forEach((row, i) => {
    const rawYear = cleanText(row[yearCol]);
    const rawMonth = cleanText(row[monthCol]);
    const eq = cleanText(row[equipCol]);
    const rawAgenda = cleanText(row[agendaCol]);
    if (rawYear === "" && rawMonth === "" && eq === "" && rawAgenda === "") return; // fila vacía
    const where = `fila ${i + 2}`;

    const year = parseNumber(rawYear);
    if (year === null || !isFinite(year) || Math.floor(year) !== year || year < 2000 || year > 2100) {
      issues.add("agenda-bad-year", "warning", "Filas de capacidad de agenda con año inválido (se descartan).", `${where}: "${rawYear}"`);
      return;
    }
    const mi = parseMonthIndex(rawMonth);
    if (mi === null) {
      issues.add("agenda-unknown-month", "warning", "Filas de capacidad de agenda con mes no reconocido (se descartan).", `${where}: "${rawMonth}"`);
      return;
    }
    if (eq === "") {
      issues.add("agenda-no-equipment", "warning", "Filas de capacidad de agenda sin equipo (se descartan).", where);
      return;
    }
    const hours = parseNumber(rawAgenda);
    if (hours === null) {
      issues.add("agenda-bad-value", "warning", "Filas con capacidad de agenda vacía o no numérica (el mes queda sin datos de agenda).", `${eq} ${MONTH_NAMES[mi]} ${year}: "${rawAgenda}"`);
      return;
    }
    if (hours < 0) {
      issues.add("agenda-negative", "warning", "Filas con capacidad de agenda negativa (se descartan).", `${eq} ${MONTH_NAMES[mi]} ${year}: ${hours}`);
      return;
    }

    const month = MONTH_NAMES[mi];
    if (!agenda[eq]) agenda[eq] = {};
    if (!agenda[eq][year]) agenda[eq][year] = {};
    if (agenda[eq][year][month] !== undefined) {
      issues.add("agenda-duplicate", "warning", "Equipo y mes repetidos en la hoja de capacidad de agenda (se usa la última fila).", `${eq} ${month} ${year}`);
    }
    agenda[eq][year][month] = hours;
  });

  return { agenda, issues: issues.toArray() };
};
