import React from "react";
import { MonthlyDetailModal } from "../components/MonthlyDetailModal";
import { useModel } from "../model/ModelContext";

/** Ventana de detalle mes a mes de la tabla de la vista 1 (con los meses elegidos en el selector). */
export const FleetDetailModal: React.FC = () => {
  const { fleet, fleetDetail, setFleetDetail, fleetDetailRows, selectedYear, agendaSummary } = useModel();
  if (!fleetDetail || !fleet) return null;
  const summary = fleetDetail.eq === null ? fleet.total : fleet.rows.filter(r => r.eq === fleetDetail.eq)[0];
  const agendaStat = !agendaSummary ? undefined : (fleetDetail.eq === null ? agendaSummary.total : agendaSummary.rows.filter(r => r.label === fleetDetail.eq)[0]);
  const targetSummary = agendaSummary
    ? { target: agendaStat ? agendaStat.targetStudies : null, gap: agendaStat ? agendaStat.studyGap : null, basis: 'agenda' as const }
    : { target: summary ? summary.targetStudies : null, gap: summary ? summary.studyGap : null, basis: 'potential' as const };
  return (
    <MonthlyDetailModal
      detail={fleetDetail}
      onClose={() => setFleetDetail(null)}
      months={fleetDetailRows}
      summary={summary}
      targetSummary={targetSummary}
      year={selectedYear}
      totalLabel="Total Flota Activa"
    />
  );
};
