import React, { useState } from "react";
import { ChevronDown, ChevronUp } from "lucide-react";

export const CollapsibleSection: React.FC<{
  title: string; subtitle?: string; icon: React.ReactNode; headerControls?: React.ReactNode; children: React.ReactNode; defaultOpen?: boolean; bgHeader?: string;
}> = ({ title, subtitle, icon, headerControls, children, defaultOpen = false, bgHeader = "bg-white" }) => {
  const [isOpen, setIsOpen] = useState(defaultOpen);
  return (
    <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden mb-6 print:border-none print:shadow-none print:mb-8">
      <div 
        className={`p-5 flex flex-col xl:flex-row justify-between xl:items-center gap-4 cursor-pointer hover:bg-gray-50/50 transition-colors select-none ${bgHeader} ${isOpen ? 'border-b border-gray-200 print:border-b-2 print:border-gray-800' : ''}`}
        onClick={() => setIsOpen(!isOpen)}
      >
        <div className="flex items-center gap-3">
          <div className="shrink-0 print:text-gray-800">{icon}</div>
          <div>
             <h3 className="text-lg font-bold text-gray-800">{title}</h3>
             {subtitle && <p className="text-sm text-gray-500 mt-0.5 font-normal print:hidden">{subtitle}</p>}
          </div>
        </div>
        <div className="flex items-center gap-4 justify-between xl:justify-end w-full xl:w-auto print:hidden" onClick={e => e.stopPropagation()}>
           {headerControls && (
             <div className="flex-1 overflow-x-auto custom-scrollbar">
                {headerControls}
             </div>
           )}
           <button onClick={() => setIsOpen(!isOpen)} className="p-1.5 rounded-full hover:bg-gray-200 transition-colors shrink-0 bg-white border border-gray-200 shadow-sm">
              {isOpen ? <ChevronUp size={20} className="text-gray-600"/> : <ChevronDown size={20} className="text-gray-600"/>}
           </button>
        </div>
      </div>
      <div className={`${isOpen ? 'block' : 'hidden print:block'} p-6 bg-white animate-in slide-in-from-top-2 duration-200 print:p-0 print:pt-4`}>
        {children}
      </div>
    </div>
  );
};
