import React, { useState } from "react";
import { MONTH_NAMES, TARGET_UTILIZATION } from "../config";
import * as calc from "../calc";
import { AgendaCompositionModal } from "../components/AgendaCompositionModal";
import { FleetTable } from "../components/FleetTable";
import { FxRateControl } from "../components/FxRateControl";
import { useModel } from "../model/ModelContext";

/** Vista 1: utilización promedio anual de cada equipo contra el objetivo, con los meses elegidos en el selector. */
export const FleetSummaryTable: React.FC = () => {
  const { fleet, toggleEq, selectedYear, excludedMonthsFleet, fleetMonthsWithData, setFleetDetail, usingSimulatedTimes, agendaSummary, fleetContracts, fx, fxStatus, setFxManual } = useModel();
  // Ventana de distribución por categoría de la agenda: undefined = cerrada, null = total de la flota
  const [agendaDetail, setAgendaDetail] = useState<string | null | undefined>(undefined);
  if (!fleet) return null;

  const months = MONTH_NAMES.filter(m => fleetMonthsWithData.has(m) && !excludedMonthsFleet.has(m));
  const isPartial = months.length < fleetMonthsWithData.size;
  const period = months.length === 0 ? '' : `${calc.describeMonths(months)} ${selectedYear} · ${months.length} ${months.length === 1 ? 'mes' : 'meses'}`;
  const wording = calc.periodWording(months.length, selectedYear);
  const hasArs = !!fleetContracts && fleetContracts.rows.some(r => r.monthlyArs > 0);
  const detailStat = agendaSummary && agendaDetail !== undefined
    ? (agendaDetail === null ? agendaSummary.total : agendaSummary.rows.filter(r => r.label === agendaDetail)[0])
    : undefined;

  return (
    <>
      <FleetTable
        title={`${wording.util} vs Objetivo`}
        period={period}
        utilHeader={wording.util}
        studiesHeader={wording.studies}
        totalLabel="Total Flota Activa"
        fleet={fleet}
        agenda={agendaSummary || undefined}
        contracts={fleetContracts || undefined}
        onAgendaDetail={agendaSummary ? setAgendaDetail : undefined}
        onToggleEq={toggleEq}
        onDetail={setFleetDetail}
        badges={<>
          {hasArs && <FxRateControl rate={fx.rate} source={fx.source} date={fx.date} status={fxStatus} onChange={setFxManual} />}
          {usingSimulatedTimes && (
            <span className="text-[10px] font-black uppercase bg-amber-100 text-amber-800 px-2 py-1 rounded">Con tiempos simulados</span>
          )}
        </>}
        footnote={<>
          Destildar un equipo lo saca del total y de los gráficos de abajo; su demanda no se reparte entre los demás (para eso está el simulador).
          Hacé clic en la utilización o en el promedio de estudios para ver el detalle mes a mes.
          {agendaSummary
            ? ` Cobertura de agenda = horas de agenda / horas de clínica abierta (horas hábiles); utilización efectiva = horas de adquisición / horas de agenda (hacé clic para ver cómo se reparte entre Neuro, Cuerpo y Commodities). La agenda se limita a las horas hábiles de cada mes y un mes sin dato de agenda queda fuera de ambas. Estudios objetivo = estudios que cabrían en el ${TARGET_UTILIZATION} % de las horas de agenda abierta al tiempo promedio por estudio de la mezcla real de cada equipo; solo cuentan los meses con agenda (los años o equipos sin agenda muestran "—") y el total suma los objetivos de cada equipo. La diferencia es realizados menos objetivo.`
            : ` Estudios objetivo = estudios que cabrían en el ${TARGET_UTILIZATION} % de las horas hábiles al tiempo promedio por estudio de la mezcla real de cada equipo en los meses elegidos; el total suma los objetivos de cada equipo. La diferencia es realizados menos objetivo.`}
          {fleetContracts && ` Contrato mensual = importe del contrato de mantenimiento vigente (la parte en pesos se convierte con el dólar oficial vendedor). Mantenimiento por estudio = contrato mensual × meses considerados / estudios hechos; usa el contrato vigente para todos los meses (la hoja no guarda contratos anteriores).${fleetContracts.missingRate ? ' * Falta la cotización: solo incluye la parte en USD.' : ''}`}
          {isPartial && ' Hay meses fuera de la selección: la utilización, los promedios y los totales cubren solo los meses elegidos.'}
        </>}
      />
      <AgendaCompositionModal
        stat={detailStat}
        name={agendaDetail === null || agendaDetail === undefined ? 'Total Flota Activa' : agendaDetail}
        year={selectedYear}
        onClose={() => setAgendaDetail(undefined)}
      />
    </>
  );
};
