import React from "react";
import { Clock, Download, UploadCloud } from "lucide-react";
import { DEFAULT_STUDY_MINUTES } from "../config";
import * as calc from "../calc";
import { CollapsibleSection } from "../components/CollapsibleSection";
import { useModel } from "../model/ModelContext";

export const TimesTableSection: React.FC = () => {
  const { data, selectedEquipment, groupingLevel, timeTableView, setTimeTableView, setCustomTimes, handleDownloadSimulationCSV, handleImportSimulationCSV, tableData, isSimulating } = useModel();

  return (
    <>
      <CollapsibleSection 
         title="Tabla con detalle de Tiempos de duración RMI agrupadas por Categoría o por Estudio" 
         icon={<Clock className="text-blue-600" size={24}/>} 
         defaultOpen={false}
         headerControls={
           <div className="flex items-center gap-3">
                <div className="flex gap-2">
                  {isSimulating && <button onClick={handleDownloadSimulationCSV} className="bg-gray-100 hover:bg-gray-200 text-gray-700 px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-2 transition-colors shadow-sm border border-gray-200">
                      <Download size={14}/> Exportar CSV
                  </button>}
                  <label className="bg-purple-600 hover:bg-purple-700 text-white px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-2 transition-colors shadow-sm cursor-pointer">
                      <UploadCloud size={14}/> Importar Tiempos CSV
                      <input type="file" accept=".csv" className="hidden" onChange={handleImportSimulationCSV} />
                  </label>
                </div>
              <div className="flex bg-gray-100 p-1 rounded-lg">
                <button onClick={() => setTimeTableView('equipo')} className={`px-4 py-1.5 text-xs font-bold rounded-md ${timeTableView === 'equipo' ? 'bg-white shadow-sm' : 'text-gray-500'}`}>Equipo Actual</button>
                <button onClick={() => setTimeTableView('general')} className={`px-4 py-1.5 text-xs font-bold rounded-md ${timeTableView === 'general' ? 'bg-white shadow-sm' : 'text-gray-500'}`}>General (Matriz)</button>
              </div>
           </div>
         }
      >
        <div className="overflow-x-auto max-h-[400px]">
          {timeTableView === 'equipo' ? (
            <table className="w-full text-sm text-left">
              <thead className="bg-gray-50 text-xs text-gray-500 uppercase sticky top-0 z-10">
                <tr>
                  <th className="px-6 py-4">
                      {groupingLevel === 'principal' ? 'Categoría Principal' : groupingLevel === 'secundaria' ? 'Categoría Secundaria' : groupingLevel === 'todo' ? 'General' : 'Tipo de Estudio'}
                  </th>
                  <th className="px-6 py-4 text-center">Representación del total en el equipo</th>
                  <th className="px-6 py-4 text-center border-l border-gray-200">
                      Tiempo {groupingLevel !== 'estudio' ? 'Promedio Ponderado' : 'Original'} (min)
                  </th>
                  <th className="px-6 py-4 text-center bg-purple-50 text-purple-800 border-l border-gray-200">Tiempo Simulado (min)</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {tableData.map((row, idx) => (
                  <tr key={idx} className={`hover:bg-gray-50 transition-colors ${row.isDefault && groupingLevel === 'estudio' ? 'bg-amber-50/40 border-l-4 border-l-amber-400' : ''}`}>
                    <td className="px-6 py-3 font-medium text-gray-700">{row.tipo}</td>
                    <td className="px-6 py-3 text-center font-bold text-gray-500">{(row.proporcion * 100).toFixed(2)}%</td>
                    <td className="px-6 py-3 text-center border-l border-gray-100">
                      <span className={`font-bold ${row.isDefault ? 'text-orange-500' : 'text-gray-700'}`}>{row.tiempo}</span>
                      {row.isDefault && groupingLevel === 'estudio' && <span className="inline-block ml-2 text-[9px] font-bold bg-orange-100 text-orange-600 px-1.5 py-0.5 rounded tracking-wider">DEFAULT</span>}
                    </td>
                    <td className="px-6 py-2 text-center bg-purple-50/20 border-l border-gray-100">
                      <input 
                        type="number" placeholder={row.edicion === 'mixed' ? 'mixto' : row.tiempo.toString()} value={row.edicion === 'uniform' && row.valorEditado !== undefined ? row.valorEditado : ''} 
                        onChange={e => {
                          const val = e.target.value;
                          const studies = calc.studiesInGroup(data, groupingLevel, row.tipo);
                          setCustomTimes(prev => calc.setCustomTime(prev, selectedEquipment, studies, val === '' || isNaN(parseFloat(val)) ? null : parseFloat(val)));
                        }} 
                        className={`w-20 text-center font-bold p-1 rounded outline-none transition-all ${row.edicion && row.edicion !== 'none' ? 'bg-purple-100 border border-purple-400 text-purple-900 ring-2 ring-purple-100' : 'bg-white border border-gray-300 text-gray-600 focus:border-purple-400'}`} 
                      />
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          ) : (
            <table className="w-full text-[10px] text-left">
              <thead className="bg-gray-50 uppercase sticky top-0 z-10">
                <tr><th className="px-4 py-3 sticky left-0 bg-gray-50 border-r">Estudio</th>{data.equipments.map(eq => <th key={eq} className="px-2 py-3 text-center min-w-[80px]">{eq}</th>)}</tr>
              </thead>
              <tbody className="divide-y">
                {data.studyTypes.sort().map(tipo => (
                  <tr key={tipo} className="hover:bg-blue-50/50">
                    <td className="px-4 py-2 font-bold sticky left-0 bg-white border-r">
                       {tipo} <br/><span className="text-[8px] font-normal text-gray-400">{data.studyHierarchy[tipo]?.principal}</span>
                    </td>
                    {data.equipments.map(eq => {
                      const t = data.times[eq]?.[tipo];
                      return <td key={eq} className={`text-center font-bold ${t?.isDefault ? 'text-orange-500 bg-orange-50/20' : 'text-gray-500'}`}>{t?.value || DEFAULT_STUDY_MINUTES}</td>
                    })}
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </CollapsibleSection>
    </>
  );
};
