import React, { useState } from "react";
import { Database } from "lucide-react";
import { DEPENDENCY_THRESHOLD, MONTH_NAMES } from "../config";
import { CollapsibleSection } from "../components/CollapsibleSection";
import { useModel } from "../model/ModelContext";

export const SpecializationSection: React.FC = () => {
  const { data, excludedMonthsMatrix, matrixRowLevel, setMatrixRowLevel, studyEqMetric, setStudyEqMetric, toggleMonthMatrix, handleDrillDown, studyEqMatrixData, getHeatmapColorClass } = useModel();

  // Filtro de dependencia: sólo las filas donde un equipo produce más del umbral de los estudios de la fila
  const [onlyDependent, setOnlyDependent] = useState<boolean>(false);
  const isDependent = (eq: string, row: typeof studyEqMatrixData.rows[number]) => row.eqData[eq].count > 0 && row.eqData[eq].pct > DEPENDENCY_THRESHOLD;
  const visibleRows = onlyDependent ? studyEqMatrixData.rows.filter(row => data.equipments.some(eq => isDependent(eq, row))) : studyEqMatrixData.rows;

  return (
    <>
      <CollapsibleSection 
        title="Matriz con el perfil de especialización de cada equipo" 
        subtitle="Analiza la distribución de estudios o categorías cruzada directamente contra cada equipo operativo. Haz clic para ver desglose."
        icon={<Database className="text-indigo-600" size={24}/>} 
        bgHeader="bg-indigo-50/30"
        defaultOpen={false}
        headerControls={
          <div className="flex flex-col sm:flex-row items-center gap-3 shrink-0">
             <div className="flex items-center gap-2 bg-white px-2 py-1 rounded-lg border shadow-sm">
               <span className="text-[10px] font-bold text-gray-500 uppercase">Nivel de agrupación:</span>
               <select value={matrixRowLevel} onChange={e => setMatrixRowLevel(e.target.value as any)} className="bg-transparent text-sm font-bold text-gray-700 outline-none cursor-pointer">
                 <option value="principal">Categoría Principal</option>
                 <option value="secundaria">Categoría Secundaria</option>
                 <option value="estudio">Nombre del Estudio</option>
               </select>
             </div>
             <div className="flex bg-gray-100 p-1 rounded-lg border border-gray-200">
               <button onClick={() => setStudyEqMetric('cantidad')} className={`px-4 py-1.5 text-xs font-bold rounded-md transition-all ${studyEqMetric === 'cantidad' ? 'bg-white text-indigo-700 shadow-sm border border-indigo-100' : 'text-gray-500 hover:text-gray-700'}`}>Cantidad de estudios</button>
               <button onClick={() => setStudyEqMetric('tiempo')} className={`px-4 py-1.5 text-xs font-bold rounded-md transition-all ${studyEqMetric === 'tiempo' ? 'bg-white text-indigo-700 shadow-sm border border-indigo-100' : 'text-gray-500 hover:text-gray-700'}`}>Horas netas usadas para la categoría</button>
               <button onClick={() => setStudyEqMetric('porcentaje')} className={`px-4 py-1.5 text-xs font-bold rounded-md transition-all ${studyEqMetric === 'porcentaje' ? 'bg-white text-indigo-700 shadow-sm border border-indigo-100' : 'text-gray-500 hover:text-gray-700'}`}>% del total de la categoría producido</button>
             </div>
          </div>
        }
      >
        {/* SELECTOR DE MESES LOCAL DE LA MATRIZ */}
        <div className="flex flex-wrap items-center justify-between gap-4 mb-4 bg-gray-50 p-2 px-4 rounded-xl border border-gray-200">
            <button
              onClick={() => setOnlyDependent(!onlyDependent)}
              title={`Muestra sólo las filas donde un único equipo produjo más del ${DEPENDENCY_THRESHOLD} % de los estudios (cantidad) de esa fila`}
              className={`px-3 py-1.5 text-xs font-bold rounded-lg border transition-colors ${onlyDependent ? 'bg-rose-50 text-rose-700 border-rose-300 shadow-sm' : 'bg-white text-gray-500 border-gray-200 hover:bg-gray-100'}`}
            >
              Solo con dependencia (un equipo &gt; {DEPENDENCY_THRESHOLD} %){onlyDependent ? ` · ${visibleRows.length} ${visibleRows.length === 1 ? 'fila' : 'filas'}` : ''}
            </button>
            <span className="text-[10px] font-bold text-gray-500 uppercase">Meses Incluidos:</span>
            <div className="flex gap-1 flex-wrap">
              {MONTH_NAMES.map(m => (
                <button key={m} onClick={() => toggleMonthMatrix(m)} className={`px-2 py-1 text-[10px] font-bold rounded border ${!excludedMonthsMatrix.has(m) ? 'bg-white border-indigo-300 text-indigo-700 shadow-sm' : 'bg-gray-200 text-gray-400 border-transparent'}`}>{m.substring(0, 3)}</button>
              ))}
            </div>
        </div>

        <div className="overflow-x-auto max-h-[600px] custom-scrollbar">
          <table className="w-full text-sm text-left">
            <thead className="text-[10px] text-gray-500 uppercase bg-gray-50 border-b border-gray-200 sticky top-0 z-20">
              <tr>
                <th className="px-4 py-4 font-bold sticky left-0 bg-gray-50 z-30 w-[240px] border-r">
                  {matrixRowLevel === 'principal' ? 'Categoría Principal' : matrixRowLevel === 'secundaria' ? 'Categoría Secundaria' : 'Estudio'}
                </th>
                {data.equipments.map(eq => <th key={eq} className="px-2 py-4 text-center font-semibold">{eq}</th>)}
                <th className="px-4 py-4 text-center font-bold bg-indigo-50 text-indigo-800 border-l border-indigo-100 z-30">Total Global</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {visibleRows.map((row, idx) => (
                <tr key={idx} className="hover:bg-indigo-50/20 transition-colors">
                  <td className="px-4 py-3 font-bold text-gray-700 text-xs sticky left-0 bg-white shadow-[2px_0_5px_-2px_rgba(0,0,0,0.05)] border-r border-gray-100 z-10">{row.rowLabel}</td>
                  {data.equipments.map(eq => {
                    const cell = row.eqData[eq];
                    let showVal = 0;
                    if (studyEqMetric === 'cantidad') showVal = cell.count;
                    if (studyEqMetric === 'tiempo') showVal = cell.time;
                    if (studyEqMetric === 'porcentaje') showVal = cell.pct;

                    const canDrillDown = cell.count > 0 && matrixRowLevel !== 'estudio';

                    return (
                      <td key={eq} className="p-1" onClick={() => canDrillDown && handleDrillDown(eq, row.rowLabel, matrixRowLevel, MONTH_NAMES.filter(m => !excludedMonthsMatrix.has(m)), true)}>
                        <div title={isDependent(eq, row) ? `Dependencia: ${cell.pct.toFixed(1)} % de los estudios de la fila` : undefined} className={`h-8 w-full flex items-center justify-center rounded text-[11px] ${isDependent(eq, row) ? 'ring-2 ring-rose-400 ' : ''}${canDrillDown ? 'cursor-pointer hover:ring-2 hover:ring-indigo-400' : ''} ${getHeatmapColorClass(showVal, studyEqMatrixData.maxVal, studyEqMetric === 'porcentaje' ? 'porcentaje' : 'cantidad')}`}>
                          {cell.count === 0 ? "-" : (studyEqMetric === 'porcentaje' ? `${showVal.toFixed(1)}%` : (studyEqMetric === 'tiempo' ? showVal.toFixed(1) : showVal))}
                        </div>
                      </td>
                    );
                  })}
                  <td className="p-1.5 border-l border-gray-100 bg-gray-50/50 text-center font-bold text-indigo-800">
                    {studyEqMetric === 'porcentaje' ? '100%' : (studyEqMetric === 'tiempo' ? `${row.totalRowTime.toFixed(1)} hs` : row.totalRow)}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </CollapsibleSection>
    </>
  );
};
