import { CheckCircle2, Database } from "lucide-react";

export const FileUploader = ({ name, loaded, handler }: { name: string, loaded: boolean, handler: any }) => (
  <label className={`cursor-pointer px-4 py-2.5 rounded-xl flex items-center justify-between gap-3 transition-colors text-[10px] sm:text-xs font-bold border shadow-sm ${
    loaded ? 'bg-emerald-50 text-emerald-700 border-emerald-200' : 'bg-white text-gray-700 border-gray-300 hover:bg-gray-50'
  }`}>
    <div className="flex items-center gap-2 overflow-hidden">
      {loaded ? <CheckCircle2 size={16} className="shrink-0"/> : <Database size={16} className="text-gray-400 shrink-0" />}
      <span className="truncate">{name}</span>
    </div>
    <input type="file" accept=".csv" className="hidden" onChange={handler} />
  </label>
);
