import { Dataset } from "../data/types";
import { CustomTimes } from "./times";
import { availHours as availHoursOf } from "./hours";
import { monthStat } from "./utilization";

// `type` (no `interface`): el Treemap de Recharts exige que el dato admita claves arbitrarias.
export type TreemapItem = {
  name: string;
  size: number;
  count: number;
  usedHours: number;
  util: number;
  availHours: number;
};

/** Tamaño y utilización por equipo para los meses elegidos (con los tiempos simulados de cada equipo). */
export const treemapData = (
  ds: Pick<Dataset, "equipments" | "times" | "hours" | "hoursByEquipment" | "monthlyQuantities" | "actual">,
  custom: CustomTimes,
  opts: { year: number; months: string[]; magnitude: "cantidad" | "tiempo" }
): TreemapItem[] => {
  const { year, months, magnitude } = opts;
  return ds.equipments
    .map((eq) => {
      let count = 0;
      let minutes = 0;
      let availHours = 0;
      months.forEach((mes) => {
        availHours += availHoursOf(ds, eq, year, mes);
        const st = monthStat(ds, custom, eq, year, mes);
        count += st.count;
        minutes += st.simulatedMinutes;
      });
      const usedHours = minutes / 60;
      const util = availHours > 0 ? (usedHours / availHours) * 100 : 0;
      const size = magnitude === "cantidad" ? count : usedHours;
      return {
        name: eq,
        size: Math.max(0.1, Math.round(size)),
        count,
        usedHours: Math.round(usedHours),
        util,
        availHours,
      };
    })
    .filter((d) => d.size > 0)
    .sort((a, b) => b.size - a.size);
};
