import React from "react";
import { MonthlyDetailModal } from "../components/MonthlyDetailModal";
import { useModel } from "../model/ModelContext";

/** Ventana de detalle mes a mes del escenario simulado (la abren la tabla del simulador y el resumen de la simulación). */
export const SimMonthlyDetailModal: React.FC = () => {
  const { simulationYear, simFleetDetail, setSimFleetDetail, simFleetDetailRows, activeTab, ...model } = useModel();
  // En el resumen de la simulación valen los equipos elegidos allí; en el simulador, toda la flota que sigue
  const onSummary = activeTab === 'simresumen';
  const simFleet = onSummary ? model.simSummaryFleet : model.simFleet;
  const simAgenda = onSummary ? model.simSummaryAgenda : model.simAgenda;
  if (!simFleet) return null;
  const shown = simFleet.sim.rows.filter(r => r.isActive);
  const total = simFleet.sim.total;
  const summary = simFleetDetail
    ? (simFleetDetail.eq === null ? total : shown.filter(r => r.eq === simFleetDetail.eq)[0])
    : undefined;
  const agendaStat = simFleetDetail && simAgenda
    ? (simFleetDetail.eq === null ? simAgenda.sim.total : simAgenda.sim.rows.filter(r => r.label === simFleetDetail.eq)[0])
    : undefined;
  const targetSummary = simAgenda
    ? { target: agendaStat ? agendaStat.targetStudies : null, gap: agendaStat ? agendaStat.studyGap : null, basis: 'agenda' as const }
    : { target: summary ? summary.targetStudies : null, gap: summary ? summary.studyGap : null, basis: 'potential' as const };
  return (
    <MonthlyDetailModal
      detail={simFleetDetail}
      onClose={() => setSimFleetDetail(null)}
      months={simFleetDetailRows}
      summary={summary}
      targetSummary={targetSummary}
      year={simulationYear}
      totalLabel="Total Flota Simulada"
      scenarioLabel="escenario simulado"
    />
  );
};
