import { DEFAULT_STUDY_MINUTES } from "../config";
import { Dataset } from "../data/types";
import { groupKey, GroupingLevel } from "./grouping";

/**
 * Tiempos simulados: equipo -> estudio -> minutos.
 * Un tiempo simulado vale SOLO para ese estudio en ese equipo. Si se edita una
 * fila de categoría, se guarda uno por cada estudio de la categoría en ese equipo.
 */
export type CustomTimes = Record<string, Record<string, number>>;

type TimesSource = Pick<Dataset, "times">;

/** Minutos del catálogo (con el valor por defecto cuando es X, vacío o no existe). */
export const catalogMinutes = (ds: TimesSource, eq: string, study: string): number => {
  const rec = ds.times[eq] ? ds.times[eq][study] : undefined;
  return (rec && rec.value) || DEFAULT_STUDY_MINUTES;
};

/** Minutos efectivos: el simulado si existe para ese equipo y estudio; si no, el del catálogo. */
export const minutesFor = (ds: TimesSource, custom: CustomTimes, eq: string, study: string): number => {
  const c = custom[eq] ? custom[eq][study] : undefined;
  return c !== undefined ? c : catalogMinutes(ds, eq, study);
};

export const hasCustomTimes = (custom: CustomTimes, eq?: string): boolean => {
  if (eq) return !!custom[eq] && Object.keys(custom[eq]).length > 0;
  return Object.keys(custom).some((e) => Object.keys(custom[e]).length > 0);
};

/** Estudios del catálogo que pertenecen a un grupo (según el nivel de agrupación). */
export const studiesInGroup = (
  ds: Pick<Dataset, "studyTypes" | "studyHierarchy">,
  level: GroupingLevel,
  group: string
): string[] => ds.studyTypes.filter((st) => groupKey(ds.studyHierarchy, st, level) === group);

/**
 * Fija (o borra, con minutes = null) el tiempo simulado de un conjunto de
 * estudios en un equipo. No modifica el objeto recibido.
 */
export const setCustomTime = (
  custom: CustomTimes,
  eq: string,
  studies: string[],
  minutes: number | null
): CustomTimes => {
  const next: CustomTimes = { ...custom };
  const forEq: Record<string, number> = { ...(next[eq] || {}) };
  studies.forEach((st) => {
    if (minutes === null || !isFinite(minutes)) delete forEq[st];
    else forEq[st] = minutes;
  });
  if (Object.keys(forEq).length === 0) delete next[eq];
  else next[eq] = forEq;
  return next;
};

export const clearCustomTimes = (custom: CustomTimes, eq: string): CustomTimes => {
  const next: CustomTimes = { ...custom };
  delete next[eq];
  return next;
};

/** Estado de un grupo de estudios en un equipo: sin cambios, un único valor, o valores mezclados. */
export const groupCustomState = (
  custom: CustomTimes,
  eq: string,
  studies: string[]
): { state: "none" | "uniform" | "mixed"; value?: number } => {
  const forEq = custom[eq] || {};
  const values: number[] = [];
  let withValue = 0;
  studies.forEach((st) => {
    if (forEq[st] !== undefined) {
      withValue++;
      values.push(forEq[st]);
    }
  });
  if (withValue === 0) return { state: "none" };
  const allSame = withValue === studies.length && values.every((v) => v === values[0]);
  return allSame ? { state: "uniform", value: values[0] } : { state: "mixed" };
};

/**
 * Convierte el formato anterior (un solo diccionario global cuyas claves eran
 * nombres de estudio o de categoría) al formato actual. Como el formato viejo no
 * guardaba el equipo, se aplica a todos los equipos. Si la clave coincide con un
 * estudio se toma como estudio; si no, como categoría secundaria; si no, principal.
 */
export const migrateLegacyCustomTimes = (
  legacy: Record<string, number>,
  ds: Pick<Dataset, "studyTypes" | "studyHierarchy" | "equipments">
): CustomTimes => {
  let out: CustomTimes = {};
  Object.keys(legacy).forEach((key) => {
    const minutes = legacy[key];
    if (typeof minutes !== "number" || !isFinite(minutes)) return;
    let studies = studiesInGroup(ds, "estudio", key);
    if (studies.length === 0) studies = studiesInGroup(ds, "secundaria", key);
    if (studies.length === 0) studies = studiesInGroup(ds, "principal", key);
    if (studies.length === 0) return;
    ds.equipments.forEach((eq) => {
      out = setCustomTime(out, eq, studies, minutes);
    });
  });
  return out;
};

/** Valida un objeto cargado desde un archivo: devuelve sólo entradas numéricas válidas. */
export const sanitizeCustomTimes = (raw: unknown): CustomTimes => {
  const out: CustomTimes = {};
  if (!raw || typeof raw !== "object") return out;
  const obj = raw as Record<string, unknown>;
  Object.keys(obj).forEach((eq) => {
    const inner = obj[eq];
    if (!inner || typeof inner !== "object") return;
    const clean: Record<string, number> = {};
    Object.keys(inner as Record<string, unknown>).forEach((st) => {
      const v = (inner as Record<string, unknown>)[st];
      if (typeof v === "number" && isFinite(v)) clean[st] = v;
    });
    if (Object.keys(clean).length > 0) out[eq] = clean;
  });
  return out;
};

/** ¿El objeto es del formato anterior (valores numéricos en el primer nivel)? */
export const isLegacyCustomTimes = (raw: unknown): raw is Record<string, number> => {
  if (!raw || typeof raw !== "object") return false;
  const vals = Object.keys(raw as object).map((k) => (raw as Record<string, unknown>)[k]);
  return vals.length > 0 && vals.every((v) => typeof v === "number");
};
