import { MONTH_NAMES } from "../config";
import { Dataset } from "../data/types";
import { availHours } from "./hours";
import { equipmentMonthLoad, sumCategories } from "./fleet";
import { CustomTimes } from "./times";

// Serie mensual de productividad entre dos meses (puede cruzar años): utilización, estudios u horas usadas,
// por equipo y para el total de la flota activa. Sólo se incluyen los meses con datos cargados.

export const TOTAL_SERIES = "Total flota activa";

export type SeriesMetric = "utilizacion" | "estudios" | "horas";

export interface MonthRef {
  year: number;
  /** Índice del mes (0 = enero). */
  month: number;
}

export interface SeriesPoint {
  label: string;
  year: number;
  mes: string;
  [series: string]: string | number | null;
}

type Source = Pick<Dataset, "times" | "monthlyQuantities" | "studyHierarchy" | "hours" | "hoursByEquipment" | "maxMonthPerYear" | "equipments">;

const order = (r: MonthRef): number => r.year * 12 + r.month;

/** Meses con datos entre `from` y `to` (inclusive); si vienen al revés se intercambian. */
export const monthsBetween = (maxMonthPerYear: Record<number, number>, from: MonthRef, to: MonthRef): MonthRef[] => {
  const a = order(from) <= order(to) ? from : to;
  const b = order(from) <= order(to) ? to : from;
  const out: MonthRef[] = [];
  for (let n = order(a); n <= order(b); n++) {
    const year = Math.floor(n / 12);
    const month = n % 12;
    const max = maxMonthPerYear[year];
    if (max !== undefined && month + 1 <= max) out.push({ year, month });
  }
  return out;
};

/** Valores de la métrica por equipo y para el total de la flota activa, mes a mes. */
export const productivitySeries = (
  ds: Source,
  custom: CustomTimes,
  opts: { from: MonthRef; to: MonthRef; metric: SeriesMetric; activeEqs: Set<string> }
): SeriesPoint[] =>
  monthsBetween(ds.maxMonthPerYear, opts.from, opts.to).map(({ year, month }) => {
    const mes = MONTH_NAMES[month];
    const point: SeriesPoint = { label: `${mes.substring(0, 3)} ${year}`, year, mes };
    let totalHours = 0;
    let totalAvail = 0;
    let totalStudies = 0;
    ds.equipments.forEach((eq) => {
      const load = equipmentMonthLoad(ds, custom, eq, year, mes);
      const hours = sumCategories(load.hours);
      const studies = sumCategories(load.studies);
      const avail = availHours(ds, eq, year, mes);
      point[eq] = opts.metric === "utilizacion" ? (avail > 0 ? (hours / avail) * 100 : null) : opts.metric === "estudios" ? studies : hours;
      if (opts.activeEqs.has(eq)) {
        totalHours += hours;
        totalAvail += avail;
        totalStudies += studies;
      }
    });
    point[TOTAL_SERIES] = opts.metric === "utilizacion" ? (totalAvail > 0 ? (totalHours / totalAvail) * 100 : null) : opts.metric === "estudios" ? totalStudies : totalHours;
    return point;
  });
