import { cleanText, headersOf, IssueCollector, parseDateParts, parseNumber, resolveColumn, toIsoDate } from "./normalize";
import { ContractsResult } from "./types";

type Row = Record<string, unknown>;

/**
 * Importe con moneda tal como lo escribe la hoja: "USD 7.491,20", "$2.570.514,00", "1800", "".
 * Los puntos son de miles y la coma es el decimal (formato regional de la hoja). Devuelve null si
 * hay texto que no es un importe; una celda vacía es 0 (el contrato no tiene esa parte).
 */
export const parseMoney = (raw: unknown): number | null => {
  const text = cleanText(raw);
  if (text === "") return 0;
  const body = text.replace(/usd|u\$s|us\$|ars|\$/gi, "").replace(/\s+/g, "");
  if (body === "") return null;
  // Formato regional: "7.491,20" (miles con punto) y "2570514,5". Un único punto seguido de
  // exactamente tres dígitos y sin coma ("7.491") también es separador de miles.
  const regional = /^-?\d{1,3}(\.\d{3})+(,\d+)?$/.test(body) || /^-?\d+,\d+$/.test(body);
  if (regional) {
    const n = parseFloat(body.replace(/\./g, "").replace(",", "."));
    return isFinite(n) ? n : null;
  }
  return parseNumber(body);
};

/**
 * Hoja CONTRATOS_VIGENTES_RMI_DMO: una fila por equipo con su contrato de mantenimiento vigente.
 * Se usan: NOMBRE_EQUIPO (igual que en el acumulado), COBERTURA_CONTRATO_ACTUAL,
 * DESCRIPCION_CONTRATO_ACTUAL, INICIO_CONTRATO, IMPORTE_CONTRATO_ARS e IMPORTE_CONTRATO_USD
 * (importes mensuales). El resto de las columnas se ignora.
 */
export const parseContratos = (rows: Row[]): ContractsResult => {
  const issues = new IssueCollector("CONTRATOS");
  const contracts: ContractsResult["contracts"] = {};
  const headers = headersOf(rows);

  const nameCol = resolveColumn(headers, ["NOMBRE_EQUIPO", "Equipo", "Nombre equipo"]);
  const coverageCol = resolveColumn(headers, ["COBERTURA_CONTRATO_ACTUAL", "Cobertura"]);
  const descCol = resolveColumn(headers, ["DESCRIPCION_CONTRATO_ACTUAL", "Descripcion contrato"]);
  const startCol = resolveColumn(headers, ["INICIO_CONTRATO", "Inicio contrato"]);
  const arsCol = resolveColumn(headers, ["IMPORTE_CONTRATO_ARS", "Importe ARS"]);
  const usdCol = resolveColumn(headers, ["IMPORTE_CONTRATO_USD", "Importe USD"]);
  const missing = [
    nameCol ? "" : "NOMBRE_EQUIPO", arsCol ? "" : "IMPORTE_CONTRATO_ARS", usdCol ? "" : "IMPORTE_CONTRATO_USD",
  ].filter((x) => x !== "");
  if (!nameCol || !arsCol || !usdCol) {
    issues.add("contracts-missing-columns", "error", "Faltan columnas en la hoja de contratos.", missing.join(", "));
    return { contracts, issues: issues.toArray() };
  }

  rows.forEach((row, i) => {
    const eq = cleanText(row[nameCol]);
    const rawArs = cleanText(row[arsCol]);
    const rawUsd = cleanText(row[usdCol]);
    if (eq === "" && rawArs === "" && rawUsd === "") return; // fila vacía
    const where = `fila ${i + 2}`;
    if (eq === "") {
      issues.add("contracts-no-equipment", "warning", "Filas de contratos sin nombre de equipo (se descartan).", where);
      return;
    }
    const ars = parseMoney(rawArs);
    const usd = parseMoney(rawUsd);
    if (ars === null || usd === null || ars < 0 || usd < 0) {
      issues.add("contracts-bad-amount", "warning", "Contratos con un importe que no se pudo interpretar (el equipo queda sin contrato).", `${eq}: ARS "${rawArs}" · USD "${rawUsd}"`);
      return;
    }
    if (ars === 0 && usd === 0) {
      issues.add("contracts-no-amount", "info", "Equipos sin importe de contrato cargado (no se calcula el costo de mantenimiento).", eq);
      return;
    }
    const rawStart = startCol ? cleanText(row[startCol]) : "";
    const parts = rawStart === "" ? null : parseDateParts(rawStart);
    if (rawStart !== "" && !parts) {
      issues.add("contracts-bad-start", "info", "Contratos con fecha de inicio no interpretable (se ignora la fecha).", `${eq}: "${rawStart}"`);
    }
    if (contracts[eq]) {
      issues.add("contracts-duplicate", "warning", "Equipo repetido en la hoja de contratos (se usa la última fila).", eq);
    }
    contracts[eq] = {
      coverage: coverageCol ? cleanText(row[coverageCol]) : "",
      description: descCol ? cleanText(row[descCol]) : "",
      start: parts ? toIsoDate(parts) : "",
      ars,
      usd,
    };
  });

  return { contracts, issues: issues.toArray() };
};
