import React from "react";
import { Clock } from "lucide-react";
import { Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, Area, ComposedChart, Bar } from "recharts";
import { CollapsibleSection } from "../components/CollapsibleSection";
import { useModel } from "../model/ModelContext";

export const SimCapacitySection: React.FC = () => {
  const { data, disabledEqs, selectedSimEq, setSelectedSimEq, simChartToggles, toggleSimChart, simulationChartData } = useModel();

  return (
    <>
      {/* 1. GRÁFICO DE HORAS FUSIONADO (CON TOGGLES) */}
      <CollapsibleSection title="Capacidad vs Produccion Real Estimada (Horas Trabajadas)" subtitle="Visualiza la brecha entre el uso original del equipo y la carga extra asimilada mensualmente." icon={<Clock className="text-emerald-600" size={24}/>} defaultOpen={true}>
         <div className="bg-white border border-gray-100 rounded-xl p-6 shadow-sm flex flex-col">
            <div className="flex flex-wrap items-center justify-between gap-4 mb-6">
               <div className="flex items-center gap-2">
                  <label className="text-[10px] font-bold text-gray-500 uppercase">Equipo:</label>
                  <select value={selectedSimEq} onChange={e => setSelectedSimEq(e.target.value)} className="bg-gray-50 border border-gray-300 text-sm rounded-lg p-2 font-bold outline-none focus:ring-2 focus:ring-emerald-500">
                     {data.equipments.filter(eq => !disabledEqs.includes(eq)).map(eq => <option key={eq} value={eq}>{eq}</option>)}
                  </select>
               </div>

               <div className="flex flex-wrap gap-2 text-xs">
                  <button onClick={() => toggleSimChart('habiles')} className={`px-3 py-1.5 rounded-lg border font-bold transition-colors ${simChartToggles.habiles ? 'bg-blue-50 border-blue-200 text-blue-700' : 'bg-gray-50 border-gray-200 text-gray-400 hover:bg-gray-100'}`}>Hs Hábiles</button>
                  <button onClick={() => toggleSimChart('orig')} className={`px-3 py-1.5 rounded-lg border font-bold transition-colors ${simChartToggles.orig ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : 'bg-gray-50 border-gray-200 text-gray-400 hover:bg-gray-100'}`}>Hs Originales</button>
                  <button onClick={() => toggleSimChart('sim')} className={`px-3 py-1.5 rounded-lg border font-bold transition-colors ${simChartToggles.sim ? 'bg-orange-50 border-orange-200 text-orange-700' : 'bg-gray-50 border-gray-200 text-gray-400 hover:bg-gray-100'}`}>Hs Simuladas</button>
                  <div className="w-px h-6 bg-gray-200 self-center mx-1"></div>
                  <button onClick={() => toggleSimChart('utilOrig')} className={`px-3 py-1.5 rounded-lg border font-bold transition-colors ${simChartToggles.utilOrig ? 'bg-emerald-50 border-emerald-600 text-emerald-800' : 'bg-gray-50 border-gray-200 text-gray-400 hover:bg-gray-100'}`}>% Util Original</button>
                  <button onClick={() => toggleSimChart('utilSim')} className={`px-3 py-1.5 rounded-lg border font-bold transition-colors ${simChartToggles.utilSim ? 'bg-orange-50 border-orange-600 text-orange-800' : 'bg-gray-50 border-gray-200 text-gray-400 hover:bg-gray-100'}`}>% Util Simulada</button>
               </div>
            </div>

            <div className="w-full h-[400px]">
               <ResponsiveContainer width="100%" height="100%">
                  <ComposedChart data={simulationChartData}>
                     <CartesianGrid strokeDasharray="3 3" vertical={false} />
                     <XAxis dataKey="mes" tick={{fontSize: 12}} />
                     <YAxis yAxisId="left" tick={{fontSize: 12}} label={{ value: 'Horas', angle: -90, position: 'insideLeft', offset: 15 }}/>
                     <YAxis yAxisId="right" orientation="right" tickFormatter={v => `${v}%`} tick={{fontSize: 12}} domain={[0, (dataMax: number) => Math.max(100, Math.ceil(dataMax / 10) * 10)]} />
                     <Tooltip 
                        contentStyle={{borderRadius: '12px'}} 
                        formatter={(value: any, name: any, props: any) => {
                           if (typeof value === 'number') {
                              if (name.includes('Utilización')) return [`${value.toFixed(2)}%`, name];

                              if (name === 'Horas Trabajadas Simuladas') {
                                 const estExtra = props.payload.EstudiosSimulados;
                                 return [`${value.toFixed(1)} hs (Abarca ${estExtra} estudios)`, name];
                              }
                              if (name === 'Horas Trabajadas (Original)') {
                                 const estOrig = props.payload.EstudiosOriginales;
                                 return [`${value.toFixed(1)} hs (Abarca ${estOrig} estudios)`, name];
                              }

                              return [Number.isInteger(value) ? value : value.toFixed(1), name];
                           }
                           return [value, name];
                        }}
                     />
                     <Legend />

                     {simChartToggles.habiles && <Area yAxisId="left" type="monotone" dataKey="HorasHabiles" fill="#EFF6FF" stroke="#3B82F6" strokeWidth={2} strokeDasharray="5 5" name="Horas Hábiles Disp." />}
                     {simChartToggles.orig && <Bar yAxisId="left" dataKey="HorasTrabajadasOriginal" barSize={25} name="Horas Trabajadas (Original)" fill="#10B981" />}
                     {simChartToggles.sim && <Bar yAxisId="left" dataKey="HorasTrabajadasSimuladas" barSize={25} name="Horas Trabajadas Simuladas" fill="#F59E0B" />}

                     {simChartToggles.utilOrig && <Line yAxisId="right" type="monotone" dataKey="UtilizacionHoras" stroke="#059669" strokeWidth={3} name="Utilización Horas [%]" />}
                     {simChartToggles.utilSim && <Line yAxisId="right" type="monotone" dataKey="UtilizacionHorasSimulada" stroke="#D97706" strokeWidth={4} strokeDasharray="5 5" name="Utilización Horas Simulada [%]" />}
                  </ComposedChart>
               </ResponsiveContainer>
            </div>
         </div>
      </CollapsibleSection>
    </>
  );
};
