import { MONTH_NAMES, OWN_HOURS_SHEETS } from "../config";
import { IssueCollector } from "./normalize";
import { AccumulatedResult, AgendaResult, ContractsResult, DataIssue, HoursResult, OwnHoursResults, QualityReport, TimesResult } from "./types";

const SEVERITY_ORDER: Record<string, number> = { error: 0, warning: 1, info: 2 };

/**
 * Combina los hallazgos de cada hoja y agrega los cruces entre hojas:
 * estudios sin catálogo, equipos sin tiempos, meses sin horas hábiles, etc.
 * Es una función pura: se puede recalcular cada vez que cambian los datos.
 */
export const buildQualityReport = (
  horas: HoursResult | null,
  tiempos: TimesResult | null,
  acc: AccumulatedResult | null,
  // Hojas de horas de los equipos con tabla propia, por clave. `undefined` = no se usan (todos con la
  // general); una hoja ausente o null = todavía no se cargó.
  horasPropias?: OwnHoursResults | null,
  // Hoja de capacidad de agenda (opcional: sin ella sólo faltan los indicadores de agenda).
  capacidades?: AgendaResult | null,
  // Hoja de contratos de mantenimiento (opcional: sin ella sólo faltan los costos de mantenimiento).
  contratos?: ContractsResult | null
): QualityReport => {
  const cross = new IssueCollector("CRUCE");
  const ownResults = OWN_HOURS_SHEETS.map((s) => (horasPropias ? horasPropias[s.key] || null : null));
  const partial = ([horas, tiempos, acc, capacidades || null, contratos || null] as Array<{ issues: DataIssue[] } | null>)
    .concat(ownResults)
    .filter((x) => x !== null)
    .map((x) => (x as { issues: DataIssue[] }).issues);
  const ownIssues: DataIssue[] = ([] as DataIssue[]).concat(...partial);

  // Los cruces entre hojas sólo tienen sentido con todas las hojas cargadas.
  const ownMissing = horasPropias !== undefined && horasPropias !== null ? ownResults.some((r) => r === null) : horasPropias === null;
  if (!horas || !tiempos || !acc || ownMissing) {
    const sorted = ownIssues.sort((a, b) => SEVERITY_ORDER[a.severity] - SEVERITY_ORDER[b.severity]);
    return {
      status: sorted.some((i) => i.severity === "error") ? "errors" : sorted.some((i) => i.severity === "warning") ? "warnings" : "ok",
      issues: sorted,
      summary: {
        totalRows: acc ? acc.stats.totalRows : 0, validRows: acc ? acc.stats.validRows : 0,
        discardedRows: acc ? acc.stats.discardedRows : 0, minDate: acc ? acc.stats.minDate : null,
        maxDate: acc ? acc.stats.maxDate : null, equipments: acc ? acc.equipments.length : 0,
        studies: acc ? acc.studyTypes.length : 0, defaultTimeShare: 0,
      },
    };
  }

  // 1. Estudios del acumulado que no están en el catálogo de tiempos.
  const catalog: Record<string, true> = {};
  tiempos.studyTypes.forEach((s) => { catalog[s] = true; });
  const uncataloged: Record<string, number> = {};
  Object.keys(acc.yearlyQuantities).forEach((eq) => {
    Object.keys(acc.yearlyQuantities[eq]).forEach((yr) => {
      const counts = acc.yearlyQuantities[eq][parseInt(yr, 10)];
      Object.keys(counts).forEach((study) => {
        if (!catalog[study]) uncataloged[study] = (uncataloged[study] || 0) + counts[study];
      });
    });
  });
  const uncatNames = Object.keys(uncataloged).sort((a, b) => uncataloged[b] - uncataloged[a]);
  uncatNames.forEach((s) => {
    cross.add(
      "cross-study-not-in-catalog",
      "warning",
      "Estudios realizados que no están en el catálogo de tiempos (se asumen sin categoría y con el tiempo por defecto).",
      `${s} (${uncataloged[s]})`
    );
  });

  // 2. Equipos del acumulado sin columna de tiempos, y al revés.
  const timeEquipments: Record<string, true> = {};
  tiempos.equipments.forEach((e) => { timeEquipments[e] = true; });
  const accEquipments: Record<string, true> = {};
  acc.equipments.forEach((e) => { accEquipments[e] = true; });
  acc.equipments.forEach((e) => {
    if (!timeEquipments[e]) {
      cross.add("cross-equipment-no-times", "error", "Equipos con estudios realizados pero sin columna en el catálogo de tiempos.", e);
    }
  });
  tiempos.equipments.forEach((e) => {
    if (!accEquipments[e]) {
      cross.add("cross-equipment-no-activity", "info", "Equipos del catálogo sin estudios en el acumulado.", e);
    }
  });

  // 2b. Equipos con tabla de horas propia que no figuran en el acumulado (¿nombre mal escrito en la configuración?).
  if (horasPropias) {
    OWN_HOURS_SHEETS.forEach((sheet) => {
      if (!accEquipments[sheet.equipment]) {
        cross.add(
          "cross-own-hours-equipment-missing",
          "warning",
          "Equipos configurados con una hoja de horas propia que no aparecen en el acumulado (revisar el nombre en src/config.ts); si el nombre no coincide, usan la hoja general.",
          sheet.equipment
        );
      }
    });
  }

  // Hoja de horas que le corresponde a cada equipo (la propia, o la general).
  const hoursFor = (eq: string) => {
    const sheet = horasPropias ? OWN_HOURS_SHEETS.filter((s) => s.equipment === eq)[0] : undefined;
    const own = sheet && horasPropias ? horasPropias[sheet.key] : null;
    return { sheet, own, table: own ? own.hours : horas.hours, tableKey: sheet && own ? sheet.key : "general" };
  };

  // 3. Meses con estudios pero sin horas hábiles (la utilización no se puede calcular).
  //    Cada equipo se revisa contra la hoja de horas que le corresponde.
  const seenMonths: Record<string, true> = {};
  Object.keys(acc.actual).forEach((eq) => {
    const { sheet, own, table, tableKey } = hoursFor(eq);
    Object.keys(acc.actual[eq]).forEach((yrStr) => {
      const yr = parseInt(yrStr, 10);
      Object.keys(acc.actual[eq][yr]).forEach((mes) => {
        const key = `${tableKey}|${yr}|${mes}`;
        if (seenMonths[key]) return;
        seenMonths[key] = true;
        const h = table[yr] ? table[yr][mes] : undefined;
        if (!h) {
          cross.add(
            "cross-month-no-hours",
            "error",
            "Meses con estudios realizados pero sin horas hábiles cargadas: la utilización no se puede calcular.",
            sheet && own ? `${mes} ${yr} (hoja ${sheet.label})` : `${mes} ${yr}`
          );
        }
      });
    });
  });

  // 3b. Capacidad de agenda (si se cargó): nombres de equipo, meses sin dato y agenda mayor que las horas hábiles.
  if (capacidades) {
    const agendaYears: Record<number, true> = {};
    Object.keys(capacidades.agenda).forEach((eq) => {
      Object.keys(capacidades.agenda[eq]).forEach((yr) => { agendaYears[parseInt(yr, 10)] = true; });
      if (!accEquipments[eq] && !timeEquipments[eq]) {
        cross.add(
          "cross-agenda-equipment-unknown",
          "warning",
          "Equipos de la hoja de capacidad de agenda que no aparecen en el acumulado ni en el catálogo de tiempos (revisar el nombre).",
          eq
        );
      }
    });
    // Meses con estudios, en años que tienen agenda cargada, sin dato de agenda para ese equipo
    Object.keys(acc.actual).forEach((eq) => {
      Object.keys(acc.actual[eq]).forEach((yrStr) => {
        const yr = parseInt(yrStr, 10);
        if (!agendaYears[yr]) return;
        Object.keys(acc.actual[eq][yr]).forEach((mes) => {
          if (!(acc.actual[eq][yr][mes] > 0)) return;
          const has = capacidades.agenda[eq] && capacidades.agenda[eq][yr] && capacidades.agenda[eq][yr][mes] !== undefined;
          if (!has) {
            cross.add(
              "cross-agenda-month-missing",
              "warning",
              "Meses con estudios realizados pero sin capacidad de agenda cargada (quedan fuera de los indicadores de agenda de ese equipo).",
              `${eq} ${mes} ${yr}`
            );
          }
        });
      });
    });
    // Agenda mayor que las horas hábiles: el cálculo la limita a las horas hábiles
    Object.keys(capacidades.agenda).forEach((eq) => {
      const { table } = hoursFor(eq);
      Object.keys(capacidades.agenda[eq]).forEach((yrStr) => {
        const yr = parseInt(yrStr, 10);
        Object.keys(capacidades.agenda[eq][yr]).forEach((mes) => {
          const raw = capacidades.agenda[eq][yr][mes];
          const potential = table[yr] ? table[yr][mes] : undefined;
          if (potential !== undefined && raw > potential + 1e-9) {
            cross.add(
              "cross-agenda-over-potential",
              "info",
              "Meses en que la agenda informada supera las horas hábiles (se limita a las horas hábiles).",
              `${eq} ${mes} ${yr}: ${raw} > ${potential}`
            );
          }
        });
      });
    });
  }

  // 3c. Contratos (si se cargaron): nombres de equipo y equipos sin contrato.
  if (contratos) {
    Object.keys(contratos.contracts).forEach((eq) => {
      if (!accEquipments[eq] && !timeEquipments[eq]) {
        cross.add(
          "cross-contract-equipment-unknown",
          "warning",
          "Equipos de la hoja de contratos que no aparecen en el acumulado ni en el catálogo de tiempos (revisar el nombre en NOMBRE_EQUIPO).",
          eq
        );
      }
    });
    acc.equipments.forEach((eq) => {
      if (!contratos.contracts[eq]) {
        cross.add("cross-equipment-no-contract", "info", "Equipos con estudios pero sin contrato de mantenimiento cargado (no entran en el costo por estudio).", eq);
      }
    });
  }

  // 4. Último dato disponible (informativo: sirve para saber hasta cuándo llega el análisis).
  if (acc.stats.maxDate) {
    const [y, m, d] = acc.stats.maxDate.split("-").map(Number);
    cross.add("cross-last-date", "info", "Último estudio registrado en el acumulado.", `${d}/${m}/${y} (${MONTH_NAMES[m - 1]} ${y})`);
  }

  // 5. Peso de los tiempos por defecto (ponderado por cantidad de estudios).
  let totalQty = 0;
  let defaultQty = 0;
  Object.keys(acc.yearlyQuantities).forEach((eq) => {
    const eqTimes = tiempos.times[eq];
    Object.keys(acc.yearlyQuantities[eq]).forEach((yr) => {
      const counts = acc.yearlyQuantities[eq][parseInt(yr, 10)];
      Object.keys(counts).forEach((study) => {
        totalQty += counts[study];
        const rec = eqTimes ? eqTimes[study] : undefined;
        if (!rec || rec.isDefault) defaultQty += counts[study];
      });
    });
  });
  const defaultTimeShare = totalQty > 0 ? (defaultQty / totalQty) * 100 : 0;
  if (defaultTimeShare > 0) {
    cross.add(
      "cross-default-time-share",
      "info",
      `Estudios que usan el tiempo por defecto: ${defaultTimeShare.toFixed(1)}% del volumen (catálogo en "X" o vacío).`
    );
  }

  const issues: DataIssue[] = ownIssues
    .concat(cross.toArray())
    .sort((a, b) => SEVERITY_ORDER[a.severity] - SEVERITY_ORDER[b.severity]);

  const hasError = issues.some((i) => i.severity === "error");
  const hasWarning = issues.some((i) => i.severity === "warning");

  return {
    status: hasError ? "errors" : hasWarning ? "warnings" : "ok",
    issues,
    summary: {
      totalRows: acc.stats.totalRows,
      validRows: acc.stats.validRows,
      discardedRows: acc.stats.discardedRows,
      minDate: acc.stats.minDate,
      maxDate: acc.stats.maxDate,
      equipments: acc.equipments.length,
      studies: acc.studyTypes.length,
      defaultTimeShare,
    },
  };
};
