import { MONTH_NAMES } from "../config";
import { Dataset, StudyCounts } from "../data/types";
import { rowKey } from "./grouping";
import { CustomTimes, minutesFor } from "./times";

export type MatrixRowLevel = "principal" | "secundaria" | "estudio";
export type MatrixMetric = "cantidad" | "porcentaje" | "tiempo";

export interface MatrixCell {
  count: number;
  time: number;
  pct: number;
}
export interface MatrixRow {
  rowLabel: string;
  eqData: Record<string, MatrixCell>;
  totalRow: number;
  totalRowTime: number;
}

/** Estudios adicionales (por equipo y mes) que se suman a la carga base, p. ej. los reubicados en el simulador. */
export type ExtraLoad = Record<string, Record<string, StudyCounts>>;

/**
 * Matriz estudio (o categoría) x equipo para un año: cantidad, horas y
 * % de cada fila que absorbe cada equipo. `extra` suma carga reubicada.
 */
export const studyEquipmentMatrix = (
  ds: Pick<Dataset, "studyTypes" | "studyHierarchy" | "times" | "monthlyQuantities">,
  custom: CustomTimes,
  opts: {
    year: number;
    rowLevel: MatrixRowLevel;
    metric: MatrixMetric;
    excludedMonths: Set<string>;
    equipments: string[];
    extra?: ExtraLoad;
  }
): { rows: MatrixRow[]; maxVal: number } => {
  const { year, rowLevel, metric, excludedMonths, equipments, extra } = opts;
  const keys: Record<string, true> = {};
  ds.studyTypes.forEach((st) => {
    keys[rowKey(ds.studyHierarchy, st, rowLevel)] = true;
  });
  const sortedRowKeys = Object.keys(keys).sort();
  let globalMax = 0;

  const result: MatrixRow[] = sortedRowKeys.map((rKey) => {
    const eqData: Record<string, MatrixCell> = {};
    let totalRow = 0;
    let totalRowTime = 0;

    equipments.forEach((eq) => {
      let sumCount = 0;
      let sumTime = 0;
      MONTH_NAMES.forEach((m) => {
        if (excludedMonths.has(m)) return;
        const base = (ds.monthlyQuantities[eq] && ds.monthlyQuantities[eq][year] && ds.monthlyQuantities[eq][year][m]) || {};
        Object.keys(base).forEach((st) => {
          if (rowKey(ds.studyHierarchy, st, rowLevel) !== rKey) return;
          sumCount += base[st];
          sumTime += base[st] * minutesFor(ds, custom, eq, st);
        });
        const add = extra && extra[eq] ? extra[eq][m] : undefined;
        if (add) {
          Object.keys(add).forEach((st) => {
            if (rowKey(ds.studyHierarchy, st, rowLevel) !== rKey) return;
            sumCount += add[st];
            sumTime += add[st] * minutesFor(ds, custom, eq, st);
          });
        }
      });
      const timeHours = sumTime / 60;
      eqData[eq] = { count: sumCount, time: timeHours, pct: 0 };
      totalRow += sumCount;
      totalRowTime += timeHours;
    });

    equipments.forEach((eq) => {
      const pct = totalRow > 0 ? (eqData[eq].count / totalRow) * 100 : 0;
      eqData[eq].pct = pct;
      let v = 0;
      if (metric === "cantidad") v = eqData[eq].count;
      if (metric === "tiempo") v = eqData[eq].time;
      if (metric === "porcentaje") v = pct;
      if (v > globalMax) globalMax = v;
    });

    return { rowLabel: rKey, eqData, totalRow, totalRowTime };
  });

  return { rows: result.sort((a, b) => b.totalRow - a.totalRow), maxVal: globalMax };
};
