import React from "react";
import { PieChart as PieChartIcon } from "lucide-react";
import { Tooltip, ResponsiveContainer, Treemap } from "recharts";
import { MONTH_NAMES } from "../config";
import { CollapsibleSection } from "../components/CollapsibleSection";
import { SemaforoLegend } from "../components/Legends";
import { useModel } from "../model/ModelContext";

export const TreemapSection: React.FC = () => {
  const { excludedMonthsCap, treemapMonths, setTreemapMonths, treemapMagnitude, setTreemapMagnitude, toggleTreemapMonth, treemapData, getTreemapColor } = useModel();

  const CustomizedTreemapContent = (props: any) => {
    const { x, y, width, height, name, util, count, usedHours } = props;
    if (!name || typeof width !== 'number' || width < 10 || typeof height !== 'number' || height < 10) return null;
    const bg = getTreemapColor(util || 0);
    return (
      <g>
        <rect
          x={x} y={y} width={width} height={height}
          style={{ fill: bg, stroke: '#ffffff', strokeWidth: 2, strokeOpacity: 1, transition: 'all 0.3s ease' }}
          className="hover:opacity-80 cursor-pointer"
        />
        {width > 60 && height > 40 && (
          <text 
            x={x + width / 2} y={y + height / 2 - 8} 
            textAnchor="middle" fill="#ffffff" fontSize={13} fontWeight="600" 
            style={{ pointerEvents: 'none', textShadow: '0px 1px 4px rgba(0,0,0,0.8)' }}
          >
            {name}
          </text>
        )}
        {width > 60 && height > 40 && count !== undefined && (
          <text 
            x={x + width / 2} y={y + height / 2 + 12} 
            textAnchor="middle" fill="#ffffff" fontSize={11} fontWeight="500" opacity={0.95} 
            style={{ pointerEvents: 'none', textShadow: '0px 1px 4px rgba(0,0,0,0.8)' }}
          >
            {treemapMagnitude === 'cantidad' ? `${count} est.` : `${usedHours} hs.`} ({(util || 0).toFixed(1)}%)
          </text>
        )}
      </g>
    );
  };

  const CustomTreemapTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
       const data = payload[0].payload;
       if (!data || !data.name) return null;
       return (
          <div className="bg-white p-4 rounded-2xl shadow-xl border border-gray-100 min-w-[200px]">
             <p className="font-black text-gray-800 text-sm mb-3 border-b border-gray-100 pb-2">{data.name}</p>
             <div className="space-y-2 text-xs">
                <div className="flex justify-between items-center"><span className="font-bold text-gray-400 uppercase">Estudios:</span> <span className="font-bold text-gray-700">{data.count}</span></div>
                <div className="flex justify-between items-center"><span className="font-bold text-gray-400 uppercase">Horas Usadas:</span> <span className="font-bold text-gray-700">{data.usedHours} hs</span></div>
                <div className="flex justify-between items-center"><span className="font-bold text-gray-400 uppercase">Hs Disponibles:</span> <span className="font-bold text-gray-700">{data.availHours} hs</span></div>
                <div className="flex justify-between items-center mt-3 pt-2 border-t border-gray-100">
                   <span className="font-bold text-gray-600 uppercase text-[10px]">Utilización Real:</span> 
                   <span className="font-black text-sm" style={{color: getTreemapColor(data.util || 0)}}>{(data.util || 0).toFixed(2)}%</span>
                </div>
             </div>
          </div>
       );
    }
    return null;
  };

  return (
    <>
      <CollapsibleSection 
         title="Mapa visual estilo bursátil de distribución de la producción" 
         subtitle="Análisis de rendimiento de la flota donde el tamaño del recuadro refleja el peso operativo y el color la utilización real respecto a la máxima teórica."
         icon={<PieChartIcon className="text-blue-600" size={24}/>} 
         defaultOpen={false}
      >
        <div className="flex flex-col lg:flex-row gap-6 mb-6">
           <div className="flex-1 space-y-4">
              <div>
                <p className="text-xs font-bold text-gray-500 uppercase mb-2">1. Magnitud para el tamaño</p>
                <div className="flex bg-gray-100 p-1 rounded-lg border border-gray-200 w-max">
                  <button onClick={() => setTreemapMagnitude('cantidad')} className={`px-4 py-1.5 text-xs font-bold rounded-md transition-all ${treemapMagnitude === 'cantidad' ? 'bg-white text-blue-700 shadow-sm border border-blue-100' : 'text-gray-500 hover:text-gray-700'}`}>Cantidad Estudios</button>
                  <button onClick={() => setTreemapMagnitude('tiempo')} className={`px-4 py-1.5 text-xs font-bold rounded-md transition-all ${treemapMagnitude === 'tiempo' ? 'bg-white text-blue-700 shadow-sm border border-blue-100' : 'text-gray-500 hover:text-gray-700'}`}>Horas Usadas</button>
                </div>
              </div>
           </div>

           <div className="flex-[2]">
              <div className="flex justify-between items-center mb-2">
                 <p className="text-xs font-bold text-gray-500 uppercase">2. Meses a evaluar</p>
                 <button onClick={() => setTreemapMonths(MONTH_NAMES.filter(m => !excludedMonthsCap.has(m)))} className="text-[10px] font-bold text-blue-600 hover:underline">Seleccionar Todos</button>
              </div>
              <div className="flex bg-gray-50 p-2 rounded-lg border border-gray-200 gap-1 flex-wrap shadow-sm">
                 {MONTH_NAMES.map(m => (
                   <button key={m} onClick={() => toggleTreemapMonth(m)} disabled={excludedMonthsCap.has(m)} className={`px-2.5 py-1.5 text-[10px] uppercase font-bold rounded transition-colors ${excludedMonthsCap.has(m) ? 'bg-gray-100 text-gray-300 opacity-50 cursor-not-allowed' : (treemapMonths.includes(m) ? 'bg-blue-100 text-blue-800 border border-blue-300 shadow-sm' : 'text-gray-400 bg-white border border-gray-200 hover:bg-gray-100')}`}>
                     {m.substring(0, 3)}
                   </button>
                 ))}
              </div>
           </div>
        </div>

        <SemaforoLegend />

        <div className="h-[450px] mt-4">
           <ResponsiveContainer width="100%" height="100%">
             <Treemap
               data={treemapData}
               dataKey="size"
               aspectRatio={4 / 3}
               stroke="#fff"
               fill="#8884d8"
               content={<CustomizedTreemapContent />}
             >
               <Tooltip content={<CustomTreemapTooltip />} />
             </Treemap>
           </ResponsiveContainer>
        </div>
      </CollapsibleSection>
    </>
  );
};
