import { MONTH_NAMES } from "../config";
import { Dataset } from "../data/types";
import { groupKey, GroupingLevel } from "./grouping";

export interface CategoryGridResult {
  rows: { equipment: string; monthsData: { exactStudy: number; isExcluded: boolean }[]; ytd: number }[];
  monthTotals: Record<string, number>;
  maxReal: number;
}

/** Cantidad de estudios de un grupo (p. ej. "RMI MAMARIA") por equipo y mes. */
export const categoryGrid = (
  ds: Pick<Dataset, "equipments" | "monthlyQuantities" | "studyHierarchy">,
  opts: { year: number; level: GroupingLevel; group: string; excluded: Set<string> }
): CategoryGridResult => {
  const { year, level, group, excluded } = opts;
  const monthTotals: Record<string, number> = {};
  MONTH_NAMES.forEach((m) => {
    monthTotals[m] = 0;
  });
  let maxReal = 0;

  const rows = ds.equipments
    .map((eq) => {
      let ytd = 0;
      const monthsData = MONTH_NAMES.map((mes) => {
        let exactStudy = 0;
        const studies = (ds.monthlyQuantities[eq] && ds.monthlyQuantities[eq][year] && ds.monthlyQuantities[eq][year][mes]) || {};
        Object.keys(studies).forEach((st) => {
          if (level === "todo" || groupKey(ds.studyHierarchy, st, level) === group) exactStudy += studies[st];
        });
        if (!excluded.has(mes)) {
          monthTotals[mes] += exactStudy;
          ytd += exactStudy;
          if (exactStudy > maxReal) maxReal = exactStudy;
        }
        return { exactStudy, isExcluded: excluded.has(mes) };
      });
      return { equipment: eq, monthsData, ytd };
    })
    .sort((a, b) => b.ytd - a.ytd);

  return { rows, monthTotals, maxReal };
};
