import React from "react";
import { Activity, BarChart2, ChevronRight, Target } from "lucide-react";
import { CATEGORY_COLORS } from "../constants";
import { useModel } from "../model/ModelContext";

/**
 * Cascada interactiva: categoría elegida en la torta -> equipos que la ejecutan ->
 * composición de la agenda del equipo -> desglose por categoría secundaria.
 * Los porcentajes se miden en horas (no en cantidad de estudios).
 */
export const CategoryCascade: React.FC = () => {
  const {
    g1SelectedCategory, g2SelectedEq, setG2SelectedEq, g3SelectedCategory, setG3SelectedCategory,
    categoryShare, equipmentAgenda, secondaryShare
  } = useModel();
  if (!g1SelectedCategory) return null;

  return (
    <div className="grid grid-cols-1 xl:grid-cols-3 gap-6 animate-in slide-in-from-bottom-4 duration-500">

      {/* COLUMNA 1: EQUIPOS QUE EJECUTAN LA CATEGORÍA */}
      <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden flex flex-col">
        <div className="p-5 border-b border-gray-100 flex items-center gap-3 bg-gray-50">
          <div className="w-4 h-4 rounded-full" style={{backgroundColor: CATEGORY_COLORS[g1SelectedCategory]}}></div>
          <div>
            <h3 className="font-bold text-gray-800 text-sm uppercase">Equipos ejecutando {g1SelectedCategory}</h3>
            <p className="text-[10px] text-gray-400 font-medium mt-0.5">% de las horas de la categoría</p>
          </div>
        </div>
        <div className="p-4 flex-1 overflow-y-auto custom-scrollbar">
          <div className="space-y-2">
            {categoryShare.map(d => (
              <div
                key={d.eq}
                onClick={() => setG2SelectedEq(d.eq)}
                className={`p-3 rounded-xl border cursor-pointer transition-all flex justify-between items-center group ${g2SelectedEq === d.eq ? 'bg-blue-50 border-blue-300 ring-1 ring-blue-300' : 'bg-white border-gray-100 hover:border-gray-300 hover:bg-gray-50 shadow-sm'}`}
              >
                <div>
                  <span className={`text-xs font-bold ${g2SelectedEq === d.eq ? 'text-blue-900' : 'text-gray-700'}`}>{d.eq}</span>
                  <p className="text-[10px] text-gray-400 font-medium">{d.qty.toLocaleString('es-AR')} estudios · {d.hours.toFixed(0)} hs</p>
                </div>
                <div className="flex items-center gap-3">
                  <span className={`text-sm font-black ${g2SelectedEq === d.eq ? 'text-blue-600' : 'text-gray-900'}`}>{d.pct.toFixed(1)}%</span>
                  <ChevronRight size={14} className={`transition-transform ${g2SelectedEq === d.eq ? 'text-blue-600 translate-x-1' : 'text-gray-400 group-hover:text-gray-600 group-hover:translate-x-0.5'}`}/>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* COLUMNAS 2 Y 3 */}
      {g2SelectedEq && (
        <div className="xl:col-span-2 flex flex-col gap-6 animate-in slide-in-from-left-4 duration-300">
          <div className="bg-gray-800 rounded-xl p-4 flex items-center justify-between shadow-md">
            <div className="flex items-center gap-3 text-white">
              <Activity className="text-emerald-400"/>
              <div>
                <p className="text-[10px] text-gray-400 uppercase font-bold tracking-wider mb-0.5">Analizando Equipo</p>
                <p className="text-base font-black">{g2SelectedEq}</p>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 flex-1">

            {/* COMPOSICIÓN DE LA AGENDA */}
            <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden flex flex-col">
              <div className="p-5 border-b border-gray-100 bg-gray-50 flex justify-between items-center">
                <h3 className="font-bold text-gray-800 text-sm uppercase">Composición de su Agenda</h3>
                <span className="text-[10px] font-black bg-blue-100 text-blue-800 px-2 py-1 rounded">
                  Util Total: {equipmentAgenda ? equipmentAgenda.util.toFixed(1) : '0.0'}%
                </span>
              </div>
              <div className="p-5 flex-1">
                <div className="space-y-4">
                  {equipmentAgenda && equipmentAgenda.slices.map(s => {
                    const isSelected = g3SelectedCategory === s.name;
                    const isUnused = s.name === "Tiempo Inutilizado";
                    return (
                      <div
                        key={s.name}
                        onClick={() => s.name !== "Tiempo Inutilizado" && setG3SelectedCategory(s.name)}
                        className={`group ${!isUnused ? 'cursor-pointer' : ''}`}
                      >
                        <div className="flex justify-between items-end mb-1">
                          <span className={`text-[11px] font-bold uppercase transition-colors flex items-center gap-1 ${isSelected ? 'text-gray-900' : 'text-gray-500 group-hover:text-gray-700'}`}>
                            {s.name}
                            {!isUnused && <ChevronRight size={10} className={`transition-opacity ${isSelected ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}/>}
                          </span>
                          <span className={`text-xs font-black ${isSelected ? 'text-gray-900' : 'text-gray-700'}`}>{s.pct.toFixed(1)}%</span>
                        </div>
                        <div className="w-full h-2.5 bg-gray-100 rounded-full overflow-hidden">
                          <div
                            className="h-full rounded-full transition-all duration-500 ease-out"
                            style={{ width: `${Math.min(100, s.pct)}%`, backgroundColor: CATEGORY_COLORS[s.name], opacity: isSelected ? 1 : 0.6 }}
                          ></div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>

            {/* DESGLOSE POR CATEGORÍA SECUNDARIA */}
            {g3SelectedCategory ? (
              <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden flex flex-col animate-in fade-in duration-300">
                <div className="p-5 border-b border-gray-100 bg-gray-50 flex items-center gap-3">
                  <Target className="text-gray-400" size={16}/>
                  <div>
                    <h3 className="font-bold text-gray-800 text-sm uppercase">Desglose de {g3SelectedCategory}</h3>
                    <p className="text-[10px] text-gray-400 font-medium mt-0.5">% de las horas de la categoría en este equipo</p>
                  </div>
                </div>
                <div className="p-4 flex-1 overflow-y-auto custom-scrollbar">
                  {secondaryShare.length === 0 ? (
                    <p className="text-xs text-gray-400 text-center py-8 font-medium">No hay estudios de esta categoría.</p>
                  ) : (
                    <div className="space-y-3">
                      {secondaryShare.map(d => (
                        <div key={d.name} className="flex flex-col gap-1">
                          <div className="flex justify-between items-start">
                            <span className="text-[10px] font-bold text-gray-600 uppercase w-2/3 leading-tight">
                              {d.name}
                              <span className="block text-gray-400 normal-case font-medium">{d.qty.toLocaleString('es-AR')} estudios · {d.hours.toFixed(0)} hs</span>
                            </span>
                            <span className="text-xs font-black text-gray-900">{d.pct.toFixed(1)}%</span>
                          </div>
                          <div className="w-full h-1.5 bg-gray-50 rounded-full overflow-hidden">
                            <div
                              className="h-full rounded-full"
                              style={{ width: `${d.pct}%`, backgroundColor: CATEGORY_COLORS[g3SelectedCategory] || '#000' }}
                            ></div>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              </div>
            ) : (
              <div className="bg-gray-50 rounded-2xl border border-gray-200 border-dashed flex flex-col items-center justify-center text-center p-8 text-gray-400">
                <BarChart2 size={32} className="mb-2 opacity-50"/>
                <p className="text-xs font-bold uppercase tracking-wider">Selecciona una categoría<br/>para ver su desglose interno</p>
              </div>
            )}

          </div>
        </div>
      )}
    </div>
  );
};
