import React from "react";
import { Target } from "lucide-react";
import { MONTH_NAMES } from "../config";
import { CollapsibleSection } from "../components/CollapsibleSection";
import { useModel } from "../model/ModelContext";

export const CategoryMapSection: React.FC = () => {
  const { groupingLevel, excludedMonthsCap, specificHeatmapMetric, setSpecificHeatmapMetric, selectedStudyType, handleDrillDown, specificHeatmapData, getHeatmapColorClass } = useModel();

  return (
    <>
      <CollapsibleSection 
         title="Mapa de producción de determinada Categoría o tipo de estudio" 
         subtitle="Distribución mensual exacta según el filtro global de agrupación. Haz clic para ver desglose."
         icon={<Target className="text-emerald-600" size={24}/>} 
         bgHeader="bg-emerald-50/30"
         defaultOpen={false}
         headerControls={
           <div className="flex flex-col sm:flex-row gap-3 items-center">
              <div className="flex bg-gray-100 p-1 rounded-lg border border-gray-200">
                <button onClick={() => setSpecificHeatmapMetric('cantidad')} className={`px-4 py-1.5 text-xs font-bold rounded-md transition-all ${specificHeatmapMetric === 'cantidad' ? 'bg-white text-emerald-700 shadow-sm border border-emerald-100' : 'text-gray-500 hover:text-gray-700'}`}>Cantidad de estudios</button>
                <button onClick={() => setSpecificHeatmapMetric('porcentaje')} className={`px-4 py-1.5 text-xs font-bold rounded-md transition-all ${specificHeatmapMetric === 'porcentaje' ? 'bg-white text-emerald-700 shadow-sm border border-emerald-100' : 'text-gray-500 hover:text-gray-700'}`}>% del total del mes</button>
              </div>
           </div>
         }
      >
        <div className="overflow-x-auto max-h-[500px]">
          <table className="w-full text-sm text-left">
            <thead className="text-[10px] text-gray-500 uppercase bg-gray-50 border-b border-gray-200 sticky top-0 z-20">
              <tr>
                <th className="px-4 py-4 font-bold sticky left-0 bg-gray-50 z-30 w-[240px] border-r">Equipo de Resonancia</th>
                {MONTH_NAMES.map(m => <th key={m} className="px-2 py-4 text-center font-semibold">{m.substring(0,3)}</th>)}
                <th className="px-4 py-4 text-center font-bold bg-emerald-50 text-emerald-800 border-l border-emerald-100 z-30">Acumulado YTD</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {specificHeatmapData.rows.map((row, idx) => (
                <tr key={idx} className="hover:bg-emerald-50/20 transition-colors">
                  <td className="px-4 py-3 font-bold text-gray-700 text-xs sticky left-0 bg-white shadow-[2px_0_5px_-2px_rgba(0,0,0,0.05)] border-r border-gray-100 z-10">{row.equipment}</td>
                  {row.monthsData.map((md, mIdx) => {
                    const mes = MONTH_NAMES[mIdx];
                    const totalMes = specificHeatmapData.monthTotals[mes];
                    const pct = totalMes > 0 ? (md.exactStudy / totalMes) * 100 : 0;
                    const showVal = specificHeatmapMetric === 'cantidad' ? md.exactStudy : pct;

                    const canDrillDown = !md.isExcluded && md.exactStudy > 0 && groupingLevel !== 'estudio';

                    return (
                      <td key={mIdx} className="p-1" onClick={() => canDrillDown && handleDrillDown(row.equipment, groupingLevel === 'todo' ? 'Total General' : selectedStudyType, groupingLevel, [mes], false)}>
                        <div className={`h-8 w-full flex items-center justify-center rounded text-[11px] ${canDrillDown ? 'cursor-pointer hover:ring-2 hover:ring-emerald-400' : ''} ${getHeatmapColorClass(showVal, specificHeatmapData.maxReal, specificHeatmapMetric, md.isExcluded)}`}>
                          {md.isExcluded ? "" : (md.exactStudy === 0 ? "-" : (specificHeatmapMetric === 'cantidad' ? md.exactStudy : `${pct.toFixed(1)}%`))}
                        </div>
                      </td>
                    );
                  })}
                  <td className="p-1.5 border-l border-gray-100 bg-gray-50/50 text-center font-bold text-emerald-800">
                     {groupingLevel !== 'estudio' && row.ytd > 0 ? (
                        <button onClick={() => handleDrillDown(row.equipment, groupingLevel === 'todo' ? 'Total General' : selectedStudyType, groupingLevel, MONTH_NAMES.filter(m => !excludedMonthsCap.has(m)), true)} className="w-full h-8 flex items-center justify-center rounded bg-emerald-100 text-emerald-800 hover:bg-emerald-600 hover:text-white transition-colors text-xs font-bold shadow-sm">
                           {row.ytd}
                        </button>
                     ) : row.ytd}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </CollapsibleSection>
    </>
  );
};
