import React from "react";
import { Calendar, CheckSquare, Square } from "lucide-react";
import { MONTH_NAMES } from "../config";
import { DAYS_OF_WEEK } from "../constants";
import { CollapsibleSection } from "../components/CollapsibleSection";
import { StandardLegend, SemaforoLegend } from "../components/Legends";
import { useModel } from "../model/ModelContext";

export const HourlyMapSection: React.FC = () => {
  const { data, selectedYear, excludedMonthsCap, heatmapColorScheme, setHeatmapColorScheme, selectedDays, hourlyMetric, setHourlyMetric, hourlyViewMode, setHourlyViewMode, hourlySelectedEqs, hourlySelectedMonth, setHourlySelectedMonth, toggleDay, toggleHourlyEq, hourlyHeatmapData, getHeatmapColorClass } = useModel();

  return (
    <>
      <CollapsibleSection 
         title="Mapa de producción según horario o franjas horarias" 
         subtitle="Saturación de estudios a lo largo de las 16 horas de jornada (6:00 a 21:00 hs)."
         icon={<Calendar className="text-purple-600" size={24}/>} 
         bgHeader="bg-purple-50/30"
         defaultOpen={false}
         headerControls={
           <div className="flex flex-col sm:flex-row items-center gap-3 shrink-0">
              {hourlyMetric === 'utilizacionCupo' && (
                <div className="flex bg-gray-100 p-1 rounded-lg border border-gray-200">
                  <button onClick={() => setHeatmapColorScheme('standard')} className={`flex items-center gap-1.5 px-3 py-1.5 text-xs font-bold rounded-md transition-all ${heatmapColorScheme === 'standard' ? 'bg-white text-purple-700 shadow-sm border border-purple-100' : 'text-gray-500 hover:text-gray-700'}`}>
                    Estándar
                  </button>
                  <button onClick={() => setHeatmapColorScheme('treemap')} className={`px-3 py-1.5 text-xs font-bold rounded-md transition-all ${heatmapColorScheme === 'treemap' ? 'bg-white text-emerald-700 shadow-sm border border-emerald-100' : 'text-gray-500 hover:text-gray-700'}`}>
                    Semáforo
                  </button>
                </div>
              )}
              <div className="flex bg-gray-100 p-1 rounded-lg border border-gray-200 shrink-0">
                <button onClick={() => setHourlyViewMode('horas')} className={`px-3 py-1.5 text-xs font-bold rounded-md transition-all ${hourlyViewMode === 'horas' ? 'bg-white text-purple-700 shadow-sm border border-purple-100' : 'text-gray-500 hover:text-gray-700'}`}>Por Hora</button>
                <button onClick={() => setHourlyViewMode('franjas')} className={`px-3 py-1.5 text-xs font-bold rounded-md transition-all ${hourlyViewMode === 'franjas' ? 'bg-white text-purple-700 shadow-sm border border-purple-100' : 'text-gray-500 hover:text-gray-700'}`}>Franjas (4h)</button>
                <div className="w-px h-6 bg-gray-300 mx-2"></div>
                <button onClick={() => setHourlyMetric('cantidad')} className={`px-3 py-1.5 text-xs font-bold rounded-md transition-all ${hourlyMetric === 'cantidad' ? 'bg-white text-purple-700 shadow-sm border border-purple-100' : 'text-gray-500 hover:text-gray-700'}`}>Cantidad de estudios</button>
                <button onClick={() => setHourlyMetric('porcentaje')} className={`px-3 py-1.5 text-xs font-bold rounded-md transition-all ${hourlyMetric === 'porcentaje' ? 'bg-white text-purple-700 shadow-sm border border-purple-100' : 'text-gray-500 hover:text-gray-700'}`}>Distribución % del total por franja</button>
                <button onClick={() => setHourlyMetric('utilizacionCupo')} className={`px-3 py-1.5 text-xs font-bold rounded-md transition-all ${hourlyMetric === 'utilizacionCupo' ? 'bg-white text-purple-700 shadow-sm border border-purple-100' : 'text-gray-500 hover:text-gray-700'}`}>% Utilización del total del cupo</button>
              </div>
           </div>
         }
      >
        <div className="flex flex-col lg:flex-row gap-6 mb-6 pb-6 border-b border-gray-100">
          <div className="flex-1 space-y-4">
             <div>
               <p className="text-xs font-bold text-gray-500 uppercase mb-2">1. Mes de Análisis</p>
               <select 
                 value={hourlySelectedMonth} 
                 onChange={e => setHourlySelectedMonth(e.target.value)} 
                 className="w-full max-w-[200px] bg-white border border-gray-300 text-sm rounded-lg p-2 font-bold outline-none focus:ring-2 focus:ring-purple-500 shadow-sm"
               >
                 <option value="ALL">Todo el Año ({selectedYear})</option>
                 {MONTH_NAMES.map(m => (
                   <option key={m} value={m} disabled={excludedMonthsCap.has(m)}>
                     {m} {excludedMonthsCap.has(m) ? '(Sin Datos)' : ''}
                   </option>
                 ))}
               </select>
             </div>
             <div>
               <p className="text-xs font-bold text-gray-500 uppercase mb-2">2. Días de la semana a incluir</p>
               <div className="flex bg-gray-50 p-1.5 rounded-lg border border-gray-200 gap-1 flex-wrap shadow-sm">
                  {DAYS_OF_WEEK.map(d => (
                    <button key={d.value} onClick={() => toggleDay(d.value)} className={`px-3 py-1.5 text-xs font-bold rounded transition-colors ${selectedDays.includes(d.value) ? 'bg-purple-100 text-purple-800 border border-purple-300 shadow-sm' : 'text-gray-400 bg-white border border-gray-200 hover:bg-gray-100'}`}>
                      {d.label}
                    </button>
                  ))}
               </div>
             </div>
          </div>
          <div className="flex-[2]">
             <p className="text-xs font-bold text-gray-500 uppercase mb-2 flex items-center gap-1.5">
                3. Equipos a sumar en el <span className="bg-gray-800 text-white px-1.5 rounded">Total Acumulado</span> (fila inferior)
             </p>
             <div className="flex gap-2 flex-wrap bg-gray-50 p-2 rounded-lg border border-gray-200 max-h-[120px] overflow-y-auto custom-scrollbar">
                {data.equipments.map(eq => (
                  <label key={eq} className={`flex items-center gap-1.5 text-xs font-bold px-2 py-1.5 rounded border cursor-pointer select-none transition-colors ${hourlySelectedEqs.includes(eq) ? 'bg-purple-50 border-purple-300 text-purple-800' : 'bg-white border-gray-200 text-gray-400 hover:bg-gray-50'}`}>
                    <input type="checkbox" checked={hourlySelectedEqs.includes(eq)} onChange={() => toggleHourlyEq(eq)} className="hidden" />
                    {hourlySelectedEqs.includes(eq) ? <CheckSquare size={14}/> : <Square size={14}/>}
                    <span className="truncate max-w-[120px]" title={eq}>{eq}</span>
                  </label>
                ))}
             </div>
          </div>
        </div>

        {/* REFERENCIA DE COLORES HORARIO */}
        {hourlyMetric === 'utilizacionCupo' && (
            <div className="mb-4">
               {heatmapColorScheme === 'standard' ? <StandardLegend /> : <SemaforoLegend />}
            </div>
        )}

        <div className="overflow-x-auto max-h-[500px]">
          <table className="w-full text-sm text-left">
            <thead className="text-[10px] text-gray-500 uppercase bg-gray-50 border-b border-gray-200 sticky top-0 z-20">
              <tr>
                <th className="px-4 py-4 font-bold sticky left-0 bg-gray-50 z-30 w-[240px] border-r">Equipo de Resonancia</th>
                {hourlyHeatmapData.columns.map((colLabel, i) => <th key={i} className="px-1 py-4 text-center font-semibold min-w-[36px]">{colLabel}</th>)}
                <th className="px-4 py-4 text-center font-bold bg-purple-50 text-purple-800 border-l border-purple-100 z-30">
                  {hourlyMetric === 'utilizacionCupo' ? 'Utilización Global' : 'Total Hrs'}
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {hourlyHeatmapData.rows.map((row, idx) => (
                <tr key={idx} className="hover:bg-purple-50/20 transition-colors">
                  <td className="px-4 py-3 font-bold text-gray-700 text-xs sticky left-0 bg-white shadow-[2px_0_5px_-2px_rgba(0,0,0,0.05)] border-r border-gray-100 z-10">{row.equipment}</td>
                  {row.hoursData.map((cellData, hIdx) => {
                    const pctEq = row.totalCountEq > 0 ? (cellData.count / row.totalCountEq) * 100 : 0;
                    const utilCupo = cellData.availHours > 0 ? (cellData.usedHours / cellData.availHours) * 100 : 0;

                    let showVal = 0;
                    if (hourlyMetric === 'cantidad') showVal = cellData.count;
                    else if (hourlyMetric === 'porcentaje') showVal = pctEq;
                    else if (hourlyMetric === 'utilizacionCupo') showVal = utilCupo;

                    const maxToUse = hourlyMetric === 'cantidad' ? hourlyHeatmapData.maxHourly : (hourlyMetric === 'porcentaje' ? hourlyHeatmapData.maxHourlyPct : 100);

                    return (
                      <td key={hIdx} className="p-0.5">
                        <div className={`h-8 w-full flex items-center justify-center rounded text-[10px] ${getHeatmapColorClass(showVal, maxToUse, hourlyMetric === 'utilizacionCupo' ? 'utilizacion' : 'cantidad')}`} title={`Estudios: ${cellData.count} \nHs Trabajadas: ${cellData.usedHours.toFixed(1)} \nHs Disponibles: ${cellData.availHours.toFixed(1)}`}>
                          {cellData.count === 0 ? "-" : (hourlyMetric === 'cantidad' ? cellData.count : `${showVal.toFixed(1)}%`)}
                        </div>
                      </td>
                    );
                  })}
                  <td className="p-1.5 border-l border-gray-100 bg-gray-50/50 text-center font-bold text-purple-800">
                    {hourlyMetric === 'utilizacionCupo' 
                       ? (row.totalAvailHoursEq > 0 ? ((row.totalUsedHoursEq / row.totalAvailHoursEq) * 100).toFixed(1) + '%' : '0%')
                       : row.totalCountEq
                    }
                  </td>
                </tr>
              ))}

              {/* FILA TOTALIZADORA HORARIA */}
              <tr className="bg-gray-800 border-t-2 border-gray-400">
                <td className="px-4 py-3 font-extrabold text-white text-xs sticky left-0 bg-gray-800 border-r border-gray-600 z-10 uppercase">
                  Total Acumulado
                </td>
                {hourlyHeatmapData.columns.map((col, i) => {
                  const filteredRows = hourlyHeatmapData.rows.filter(r => hourlySelectedEqs.includes(r.equipment));
                  const sumCount = filteredRows.reduce((acc, r) => acc + (r.hoursData[i]?.count || 0), 0);
                  const sumUsed = filteredRows.reduce((acc, r) => acc + (r.hoursData[i]?.usedHours || 0), 0);
                  const sumAvail = filteredRows.reduce((acc, r) => acc + (r.hoursData[i]?.availHours || 0), 0);
                  const totalAllCountSelected = filteredRows.reduce((acc, r) => acc + r.totalCountEq, 0);

                  let displayStr = '-';
                  if (sumCount > 0 || sumUsed > 0) {
                    if (hourlyMetric === 'cantidad') displayStr = sumCount.toString();
                    else if (hourlyMetric === 'porcentaje') displayStr = totalAllCountSelected > 0 ? ((sumCount / totalAllCountSelected) * 100).toFixed(1) + '%' : '0%';
                    else if (hourlyMetric === 'utilizacionCupo') displayStr = sumAvail > 0 ? ((sumUsed / sumAvail) * 100).toFixed(1) + '%' : '0%';
                  }

                  return (
                    <td key={i} className="p-1 text-center font-black text-[11px] text-white">
                      {displayStr}
                    </td>
                  );
                })}
                <td className="p-1.5 border-l border-gray-600 text-center font-black text-emerald-400">
                  {(() => {
                     const filteredRows = hourlyHeatmapData.rows.filter(r => hourlySelectedEqs.includes(r.equipment));
                     if (hourlyMetric === 'cantidad') return filteredRows.reduce((acc, r) => acc + r.totalCountEq, 0);
                     if (hourlyMetric === 'porcentaje') return '100%';

                     const allUsed = filteredRows.reduce((acc, r) => acc + r.totalUsedHoursEq, 0);
                     const allAvail = filteredRows.reduce((acc, r) => acc + r.totalAvailHoursEq, 0);
                     return allAvail > 0 ? ((allUsed / allAvail) * 100).toFixed(1) + '%' : '0%';
                  })()}
                </td>
              </tr>
            </tbody>
          </table>
        </div>
      </CollapsibleSection>
    </>
  );
};
