// Funciones puras de normalización. Sin dependencias de React ni del DOM,
// para poder probarlas de forma aislada.

import { MONTH_NAMES } from "../config";
import { DataIssue, DataSource, Severity } from "./types";

// ---------- Hallazgos ----------

/** Acumula hallazgos agrupados por código (cuenta + hasta 5 ejemplos). */
export class IssueCollector {
  private byCode: Record<string, DataIssue> = {};
  private order: string[] = [];

  constructor(private source: DataSource) {}

  add(code: string, severity: Severity, message: string, example?: string): void {
    let issue = this.byCode[code];
    if (!issue) {
      issue = { source: this.source, severity, code, message, count: 0, examples: [] };
      this.byCode[code] = issue;
      this.order.push(code);
    }
    issue.count++;
    if (example !== undefined && issue.examples.length < 5 && issue.examples.indexOf(example) === -1) {
      issue.examples.push(example);
    }
  }

  toArray(): DataIssue[] {
    return this.order.map((c) => this.byCode[c]);
  }
}

// ---------- Texto ----------

export const stripAccents = (s: string): string =>
  s.normalize("NFD").replace(/[̀-ͯ]/g, "");

/** Clave comparable: sin acentos, minúsculas, espacios colapsados. */
export const normKey = (s: string): string =>
  stripAccents(String(s)).toLowerCase().replace(/\s+/g, " ").trim();

export const cleanText = (v: unknown): string =>
  v === undefined || v === null ? "" : String(v).replace(/\s+/g, " ").trim();

// ---------- Columnas ----------

/**
 * Busca, entre los encabezados disponibles, el primero que coincida con alguno
 * de los alias (ignorando mayúsculas, acentos y espacios). Devuelve el nombre
 * real de la columna o null.
 */
export const resolveColumn = (headers: string[], aliases: string[]): string | null => {
  const wanted = aliases.map(normKey);
  for (let i = 0; i < wanted.length; i++) {
    for (let j = 0; j < headers.length; j++) {
      if (normKey(headers[j]) === wanted[i]) return headers[j];
    }
  }
  return null;
};

export const headersOf = (rows: Array<Record<string, unknown>>): string[] =>
  rows.length > 0 ? Object.keys(rows[0]) : [];

// ---------- Números ----------

/**
 * Convierte texto a número aceptando coma o punto decimal ("30", "30,5",
 * "1.234,5", "1,234.5"). Devuelve null si no es numérico.
 */
export const parseNumber = (raw: unknown): number | null => {
  if (typeof raw === "number") return isFinite(raw) ? raw : null;
  if (raw === undefined || raw === null) return null;
  let s = String(raw).trim().replace(/\s+/g, "");
  if (s === "") return null;
  const hasComma = s.indexOf(",") !== -1;
  const hasDot = s.indexOf(".") !== -1;
  if (hasComma && hasDot) {
    // El último separador es el decimal; el otro es de miles.
    if (s.lastIndexOf(",") > s.lastIndexOf(".")) s = s.replace(/\./g, "").replace(",", ".");
    else s = s.replace(/,/g, "");
  } else if (hasComma) {
    s = s.replace(",", ".");
  }
  if (!/^-?\d+(\.\d+)?$/.test(s)) return null;
  const n = parseFloat(s);
  return isFinite(n) ? n : null;
};

// ---------- Meses ----------

const MONTH_LOOKUP: Record<string, number> = (() => {
  const m: Record<string, number> = {};
  MONTH_NAMES.forEach((name, i) => {
    const k = normKey(name);
    m[k] = i;
    m[k.slice(0, 3)] = i; // abreviatura: ene, feb, mar...
  });
  m["setiembre"] = 8;
  m["sept"] = 8;
  return m;
})();

/** Devuelve el índice de mes (0-11) o null. Acepta mayúsculas, acentos y abreviaturas. */
export const parseMonthIndex = (raw: unknown): number | null => {
  const k = normKey(cleanText(raw)).replace(/\.$/, "");
  return Object.prototype.hasOwnProperty.call(MONTH_LOOKUP, k) ? MONTH_LOOKUP[k] : null;
};

// ---------- Fechas ----------

export interface DateParts {
  day: number;
  month: number; // 1-12
  year: number;
}

const daysInMonth = (year: number, month: number): number => new Date(year, month, 0).getDate();

/**
 * Interpreta "dd/mm/aaaa", "d/m/aa", "aaaa-mm-dd" y "dd-mm-aaaa".
 * Valida que sea una fecha real del calendario. Devuelve null si no lo es.
 */
export const parseDateParts = (raw: unknown): DateParts | null => {
  if (typeof raw !== "string") return null;
  const s = raw.trim();
  let day: number, month: number, year: number;
  let m = /^(\d{1,2})[/-](\d{1,2})[/-](\d{2}|\d{4})$/.exec(s);
  if (m) {
    day = parseInt(m[1], 10);
    month = parseInt(m[2], 10);
    year = parseInt(m[3], 10);
    if (m[3].length === 2) year += 2000;
  } else {
    m = /^(\d{4})-(\d{1,2})-(\d{1,2})$/.exec(s);
    if (!m) return null;
    year = parseInt(m[1], 10);
    month = parseInt(m[2], 10);
    day = parseInt(m[3], 10);
  }
  if (month < 1 || month > 12 || day < 1 || year < 1990 || year > 2100) return null;
  if (day > daysInMonth(year, month)) return null;
  return { day, month, year };
};

export const toIsoDate = (d: DateParts): string => {
  const p = (n: number, len: number) => {
    let t = String(n);
    while (t.length < len) t = "0" + t;
    return t;
  };
  return `${p(d.year, 4)}-${p(d.month, 2)}-${p(d.day, 2)}`;
};

// ---------- Horas ----------

/**
 * Devuelve la hora del día (0-23) de "7:21:15", "07:21", un decimal de día
 * (0.5 = 12h) o un número de hora. Devuelve null si no se puede interpretar.
 */
export const parseHour = (raw: unknown): number | null => {
  if (raw === undefined || raw === null) return null;
  let hour: number;
  if (typeof raw === "number") {
    hour = raw > 0 && raw < 1 ? Math.floor(raw * 24) : Math.floor(raw);
  } else {
    const s = String(raw).trim();
    if (s === "") return null;
    if (s.indexOf(":") !== -1) {
      hour = parseInt(s.split(":")[0], 10);
    } else {
      const f = parseNumber(s);
      if (f === null) return null;
      hour = f > 0 && f < 1 ? Math.floor(f * 24) : Math.floor(f);
    }
  }
  return isNaN(hour) || hour < 0 || hour > 23 ? null : hour;
};
