import React from "react";
import { MONTH_NAMES } from "../config";
import * as calc from "../calc";
import { useModel } from "../model/ModelContext";
import { SummaryPanel } from "./SummaryPanel";

/** Pestaña Resumen: la flota actual, con el año y los meses elegidos en el selector de ¿Alcanza la flota hoy?. */
export const SummaryBanners: React.FC = () => {
  const { fleet, agendaSummary, fleetContracts, dependency, toggleEq, resetEqs, activeEqs, data, selectedYear, excludedMonthsFleet, fleetMonthsWithData, setFleetDetail } = useModel();
  if (!fleet) return null;

  const months = MONTH_NAMES.filter(m => fleetMonthsWithData.has(m) && !excludedMonthsFleet.has(m));
  const period = months.length === 0 ? '' : `${calc.describeMonths(months)} ${selectedYear} · ${months.length} ${months.length === 1 ? 'mes' : 'meses'}`;

  return (
    <SummaryPanel
      scenario={false}
      year={selectedYear}
      monthsCount={months.length}
      period={period}
      fleet={fleet}
      agenda={agendaSummary}
      contracts={fleetContracts}
      dependency={dependency}
      onToggleEq={toggleEq}
      picker={{ equipments: data.equipments, selected: activeEqs, onAll: resetEqs }}
      onDetail={setFleetDetail}
      showChart={true}
    />
  );
};
