import { Dataset } from "../data/types";

/**
 * Horas hábiles de un equipo en un mes. Los equipos con tabla propia
 * (ver OWN_HOURS_SHEETS en config) usan esa; el resto, la tabla general.
 * Si la tabla del equipo no trae el mes, son 0 horas (no se cae a la general).
 */
export const availHours = (
  ds: Pick<Dataset, "hours" | "hoursByEquipment">,
  eq: string,
  year: number,
  mes: string
): number => {
  const table = ds.hoursByEquipment[eq] || ds.hours;
  return (table[year] && table[year][mes]) || 0;
};
