import React from "react";
import { SimToolbar } from "./SimToolbar";
import { SimConfigPanel } from "./SimConfigPanel";
import { SimDistributionMatrix } from "./SimDistributionMatrix";
import { SimImpact } from "./SimImpact";
import { useModel } from "../model/ModelContext";

export const SimulatorTab: React.FC = () => {
  const { disabledEqs } = useModel();
  return (
    <div className="animate-in slide-in-from-right-4 duration-300">
      <SimToolbar />
      <SimConfigPanel />

      {disabledEqs.length > 0 && (
        <>
          <SimDistributionMatrix />
          <SimImpact />
        </>
      )}
    </div>
  );
};
