import { MONTH_NAMES } from "../config";
import { Dataset } from "../data/types";
import { availHours as availHoursOf } from "./hours";
import { catalogMinutes, CustomTimes, hasCustomTimes, minutesFor } from "./times";

type Source = Pick<Dataset, "times" | "monthlyQuantities" | "actual" | "hours" | "hoursByEquipment">;

export interface MonthStat {
  count: number;
  originalMinutes: number;
  simulatedMinutes: number;
}

/** Estudios y minutos de un equipo en un mes (con tiempos del catálogo y con los simulados). */
export const monthStat = (ds: Source, custom: CustomTimes, eq: string, year: number, mes: string): MonthStat => {
  const studies = (ds.monthlyQuantities[eq] && ds.monthlyQuantities[eq][year] && ds.monthlyQuantities[eq][year][mes]) || {};
  let count = 0;
  let originalMinutes = 0;
  let simulatedMinutes = 0;
  Object.keys(studies).forEach((st) => {
    const qty = studies[st];
    count += qty;
    originalMinutes += qty * catalogMinutes(ds, eq, st);
    simulatedMinutes += qty * minutesFor(ds, custom, eq, st);
  });
  return { count, originalMinutes, simulatedMinutes };
};

const actualOf = (ds: Pick<Dataset, "actual">, eq: string, year: number, mes: string): number =>
  (ds.actual[eq] && ds.actual[eq][year] && ds.actual[eq][year][mes]) || 0;

// ---------- Serie mensual de un equipo (gráfico principal) ----------

export interface ChartMonth {
  mes: string;
  HorasHabiles: number;
  ProduccionReal: number;
  HorasTrabajadasOriginal: number;
  HorasTrabajadasSimuladas: number | null;
  UtilizacionHoras: number;
  UtilizacionHorasSimulada: number;
  EstudiosOriginales: number;
  isExcluded: boolean;
}

export const equipmentMonthly = (
  ds: Source,
  custom: CustomTimes,
  eq: string,
  year: number,
  excluded: Set<string>
): { months: ChartMonth[]; isSimulating: boolean } => {
  const isSimulating = hasCustomTimes(custom, eq);
  const months = MONTH_NAMES.map((mes) => {
    const hr = availHoursOf(ds, eq, year, mes);
    const st = monthStat(ds, custom, eq, year, mes);
    const hoursOriginal = st.originalMinutes / 60;
    const hoursSimulated = st.simulatedMinutes / 60;
    return {
      mes,
      HorasHabiles: hr,
      ProduccionReal: actualOf(ds, eq, year, mes),
      HorasTrabajadasOriginal: hoursOriginal,
      HorasTrabajadasSimuladas: isSimulating ? hoursSimulated : null,
      UtilizacionHoras: hr > 0 ? (hoursOriginal / hr) * 100 : 0,
      UtilizacionHorasSimulada: hr > 0 ? (hoursSimulated / hr) * 100 : 0,
      EstudiosOriginales: st.count,
      isExcluded: excluded.has(mes),
    };
  });
  return { months, isSimulating };
};

// ---------- Grilla equipos x meses (mapa de calor global) ----------

export interface GridCell {
  actual: number;
  max: number;
  util: number;
  usedHours: number;
  availHours: number;
  isExcluded: boolean;
}
export interface GridRow {
  equipment: string;
  monthsData: GridCell[];
  ytd: number;
}
export interface Grid {
  rows: GridRow[];
  maxMonthly: number;
  maxYtd: number;
}

/**
 * Cada equipo usa SUS propios tiempos simulados (antes, los del equipo
 * seleccionado se aplicaban a todos).
 */
export const utilizationGrid = (
  ds: Source & Pick<Dataset, "equipments">,
  custom: CustomTimes,
  year: number,
  excluded: Set<string>
): Grid => {
  let maxM = 0;
  let maxY = 0;
  const rows = ds.equipments
    .map((eq) => {
      let ytd = 0;
      const monthsData = MONTH_NAMES.map((mes) => {
        const actual = actualOf(ds, eq, year, mes);
        const hr = availHoursOf(ds, eq, year, mes);
        const usedHours = monthStat(ds, custom, eq, year, mes).simulatedMinutes / 60;
        const util = hr > 0 ? (usedHours / hr) * 100 : 0;
        if (!excluded.has(mes)) {
          if (actual > maxM) maxM = actual;
          ytd += actual;
        }
        return { actual, max: 0, util, usedHours, availHours: hr, isExcluded: excluded.has(mes) };
      });
      if (ytd > maxY) maxY = ytd;
      return { equipment: eq, monthsData, ytd };
    })
    .sort((a, b) => b.ytd - a.ytd);
  return { rows, maxMonthly: maxM, maxYtd: maxY };
};

// ---------- Utilización anual de un equipo (meses con datos) ----------

/**
 * Utilización del período: horas trabajadas / horas hábiles de los meses
 * no excluidos. Con useSimulated = true usa los tiempos simulados.
 */
export const periodUtilization = (
  ds: Source,
  custom: CustomTimes,
  eq: string,
  year: number,
  excluded: Set<string>,
  useSimulated: boolean
): { usedHours: number; availHours: number; util: number } => {
  let usedMinutes = 0;
  let availHours = 0;
  MONTH_NAMES.forEach((mes) => {
    if (excluded.has(mes)) return;
    const st = monthStat(ds, custom, eq, year, mes);
    usedMinutes += useSimulated ? st.simulatedMinutes : st.originalMinutes;
    availHours += availHoursOf(ds, eq, year, mes);
  });
  const usedHours = usedMinutes / 60;
  return { usedHours, availHours, util: availHours > 0 ? (usedHours / availHours) * 100 : 0 };
};
