import React from "react";
import { BarChart2, PieChart as PieChartIcon } from "lucide-react";
import { MONTH_NAMES } from "../config";
import { CollapsibleSection } from "../components/CollapsibleSection";
import { StandardLegend, SemaforoLegend } from "../components/Legends";
import { useModel } from "../model/ModelContext";

export const FleetMatrixSection: React.FC = () => {
  const { setShowDonutModalEq, setCellDetails, heatmapMetric, setHeatmapMetric, heatmapColorScheme, setHeatmapColorScheme, globalHeatmapData, getHeatmapColorClass } = useModel();

  return (
    <>
      <CollapsibleSection 
        title={`Matriz de producción general en cantidad y en % de utilización`} 
        subtitle="Visión global de la flota. Haz clic en las celdas o el YTD para detalles."
        icon={<BarChart2 className="text-blue-600" size={24}/>} 
        defaultOpen={false}
        headerControls={
          <div className="flex flex-col sm:flex-row gap-3 items-center">
            {heatmapMetric === 'utilizacion' && (
              <div className="flex bg-gray-100 p-1 rounded-lg border border-gray-200">
                <button onClick={() => setHeatmapColorScheme('standard')} className={`flex items-center gap-1.5 px-3 py-1.5 text-xs font-bold rounded-md transition-all ${heatmapColorScheme === 'standard' ? 'bg-white text-blue-700 shadow-sm border border-blue-100' : 'text-gray-500 hover:text-gray-700'}`}>
                  Estándar
                </button>
                <button onClick={() => setHeatmapColorScheme('treemap')} className={`px-3 py-1.5 text-xs font-bold rounded-md transition-all ${heatmapColorScheme === 'treemap' ? 'bg-white text-emerald-700 shadow-sm border border-emerald-100' : 'text-gray-500 hover:text-gray-700'}`}>
                  Semáforo
                </button>
              </div>
            )}
            <div className="flex bg-gray-100 p-1 rounded-lg border border-gray-200">
              <button onClick={() => setHeatmapMetric('cantidad')} className={`px-4 py-1.5 text-xs font-bold rounded-md transition-all ${heatmapMetric === 'cantidad' ? 'bg-white text-blue-700 shadow-sm border border-blue-100' : 'text-gray-500 hover:text-gray-700'}`}>Cantidad</button>
              <button onClick={() => setHeatmapMetric('utilizacion')} className={`px-4 py-1.5 text-xs font-bold rounded-md transition-all ${heatmapMetric === 'utilizacion' ? 'bg-white text-blue-700 shadow-sm border border-blue-100' : 'text-gray-500 hover:text-gray-700'}`}>% Utilización</button>
            </div>
          </div>
        }
      >
        {/* REFERENCIA DE COLORES */}
        {heatmapMetric === 'utilizacion' && (
            <div className="mb-4">
               {heatmapColorScheme === 'standard' ? <StandardLegend /> : <SemaforoLegend />}
            </div>
        )}
        <div className="overflow-x-auto pb-4">
          <table className="w-full text-sm text-left">
            <thead className="text-[10px] text-gray-500 uppercase bg-gray-50 border-b border-gray-200 sticky top-0 z-20">
              <tr>
                <th className="px-4 py-4 font-bold sticky left-0 bg-gray-50 z-30 w-[240px] border-r">Equipo de Resonancia</th>
                {MONTH_NAMES.map(m => <th key={m} className="px-2 py-4 text-center font-semibold">{m.substring(0,3)}</th>)}
                <th className="px-4 py-4 text-center font-bold bg-blue-50 text-blue-800 border-l border-blue-100 z-30">Acumulado YTD</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {globalHeatmapData.rows.map((row, idx) => (
                <tr key={idx} className="hover:bg-blue-50/20 transition-colors">
                  <td className="px-4 py-3 font-bold text-gray-700 text-xs sticky left-0 bg-white shadow-[2px_0_5px_-2px_rgba(0,0,0,0.05)] border-r border-gray-100 z-10">{row.equipment}</td>
                  {row.monthsData.map((md, mIdx) => (
                    <td key={mIdx} className="p-1 cursor-pointer" onClick={() => !md.isExcluded && setCellDetails({ eq: row.equipment, mes: MONTH_NAMES[mIdx], count: md.actual, usedHours: md.usedHours, availHours: md.availHours, util: md.util })}>
                      <div className={`h-10 w-full flex items-center justify-center rounded text-[11px] ${!md.isExcluded && 'hover:ring-2 hover:ring-blue-400'} transition-all ${getHeatmapColorClass(heatmapMetric === 'cantidad' ? md.actual : md.util, globalHeatmapData.maxMonthly, heatmapMetric, md.isExcluded)}`}>
                        {md.isExcluded ? "" : (md.actual === 0 ? "-" : (heatmapMetric === 'cantidad' ? md.actual : `${md.util.toFixed(1)}%`))}
                      </div>
                    </td>
                  ))}
                  <td className="p-1.5 border-l border-gray-100 bg-gray-50/50">
                    <button onClick={() => setShowDonutModalEq(row.equipment)} className="w-full h-10 flex items-center justify-center gap-1.5 rounded bg-blue-100 text-blue-800 hover:bg-blue-600 hover:text-white transition-colors text-xs font-bold shadow-sm">
                      <PieChartIcon size={14}/> {row.ytd}
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </CollapsibleSection>
    </>
  );
};
