import React from "react";
import { Briefcase } from "lucide-react";
import { MONTH_NAMES } from "../config";
import * as calc from "../calc";
import { useModel } from "../model/ModelContext";
import { SummaryPanel } from "./SummaryPanel";
import { SimMonthlyDetailModal } from "./SimMonthlyDetailModal";

/**
 * Resumen del escenario simulado: los mismos cuatro banners del Resumen, con el escenario armado en el simulador
 * (equipos dados de baja y reparto de sus estudios) y la diferencia contra la flota actual.
 */
export const SimSummaryBanners: React.FC = () => {
  const { simSummaryFleet: simFleet, simSummaryAgenda: simAgenda, simSummaryContracts: simContracts, simSummaryContractsOriginal: simContractsOriginal, simSummaryDependency: simDependency, simSummaryInactive, toggleSimSummaryEq, resetSimSummaryEqs, simulationYear, simExcludedMonths, disabledEqs, data, setSimFleetDetail, setActiveTab } = useModel();

  if (!simFleet) {
    return (
      <div className="bg-white rounded-2xl shadow-sm border border-gray-200 p-12 text-center text-gray-500">
        <Briefcase size={40} className="text-gray-300 mb-4 mx-auto" />
        <h3 className="text-lg font-medium">Todavía no hay un escenario simulado</h3>
        <p className="text-sm mt-2">Dá de baja al menos un equipo en el simulador para ver acá el resumen del escenario.</p>
        <button onClick={() => setActiveTab('simulacion')} className="mt-5 bg-orange-500 text-white px-5 py-2.5 rounded-xl font-bold text-sm hover:bg-orange-600 transition-colors">Ir al simulador</button>
      </div>
    );
  }

  const months = MONTH_NAMES.filter(m => !simExcludedMonths.has(m));
  const period = months.length === 0 ? '' : `${calc.describeMonths(months)} ${simulationYear} · ${months.length} ${months.length === 1 ? 'mes' : 'meses'}`;
  const removed = data.equipments.filter(e => disabledEqs.includes(e));
  // Se listan los equipos que siguen (también los que se dejaron afuera de las cifras, atenuados); los dados de baja van aparte
  const shown = { ...simFleet.sim, rows: simFleet.sim.rows.filter(r => removed.indexOf(r.eq) < 0) };
  const selected = new Set(data.equipments.filter(e => !simSummaryInactive.has(e)));

  return (
    <>
      <div className="bg-orange-50 border border-orange-200 rounded-2xl p-4 px-5 mb-6 flex flex-wrap items-center justify-between gap-3">
        <div>
          <p className="text-[10px] font-bold text-orange-700 uppercase tracking-wider">Escenario simulado · {simulationYear}</p>
          <p className="text-sm font-bold text-gray-800 mt-1">Equipos dados de baja: {removed.join(', ')}</p>
          <p className="text-xs text-gray-500 mt-0.5">Sus estudios se reparten según lo armado en el simulador; las cifras muestran la diferencia contra la flota actual.</p>
        </div>
        <button onClick={() => setActiveTab('simulacion')} className="bg-white text-orange-700 border border-orange-300 px-4 py-2 rounded-xl font-bold text-xs hover:bg-orange-100 transition-colors">Editar el escenario</button>
      </div>
      <SummaryPanel
        scenario={true}
        year={simulationYear}
        monthsCount={months.length}
        period={period}
        fleet={shown}
        baselineFleet={simFleet.original}
        agenda={simAgenda ? simAgenda.sim : null}
        agendaBaseline={simAgenda ? simAgenda.original : null}
        contracts={simContracts}
        contractsBaseline={simContractsOriginal}
        dependency={simDependency ? simDependency.sim : null}
        dependencyBaseline={simDependency ? simDependency.original : null}
        removed={removed}
        onToggleEq={toggleSimSummaryEq}
        picker={{ equipments: data.equipments, selected, onAll: resetSimSummaryEqs }}
        onDetail={setSimFleetDetail}
        showChart={false}
      />
      <SimMonthlyDetailModal />
    </>
  );
};
