import React, { useMemo, useState } from "react";
import { BarChart, Bar, Line, LineChart, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, ReferenceLine } from "recharts";
import { MONTH_NAMES, TARGET_UTILIZATION } from "../config";
import * as calc from "../calc";
import { useModel } from "../model/ModelContext";

type ChartKind = 'lineas' | 'barras';

const METRICS: Array<{ id: calc.SeriesMetric; label: string }> = [
  { id: 'utilizacion', label: 'Utilización (%)' },
  { id: 'estudios', label: 'Estudios' },
  { id: 'horas', label: 'Horas usadas' },
];

const TOTAL_COLOR = '#1F2937';
const SERIES_COLORS = ['#2563EB', '#10B981', '#F59E0B', '#8B5CF6', '#EF4444', '#06B6D4', '#EC4899', '#84CC16', '#F97316', '#14B8A6', '#6366F1', '#A16207'];

const order = (year: number, month: number) => year * 12 + month;
const selectClass = "bg-gray-50 border border-gray-300 text-sm rounded-lg p-2 font-bold outline-none focus:ring-2 focus:ring-blue-500";

/** Últimos 12 meses con datos cargados (o todos si hay menos). */
const defaultRange = (maxMonthPerYear: Record<number, number>, years: number[]) => {
  const withData = years.filter(y => maxMonthPerYear[y] !== undefined);
  if (withData.length === 0) return { fy: years[0] || 0, fm: 0, ty: years[0] || 0, tm: 0 };
  const lastYear = withData[withData.length - 1];
  const end = order(lastYear, maxMonthPerYear[lastYear] - 1);
  const first = order(withData[0], 0);
  const start = Math.max(end - 11, first);
  return { fy: Math.floor(start / 12), fm: start % 12, ty: Math.floor(end / 12), tm: end % 12 };
};

/** Gráfico de productividad mes a mes: utilización, estudios u horas; líneas o barras; período a elección. */
export const ProductivityChartSection: React.FC = () => {
  const { data, customTimes, activeEqs } = useModel();
  const [kind, setKind] = useState<ChartKind>('lineas');
  const [metric, setMetric] = useState<calc.SeriesMetric>('utilizacion');
  const [range, setRange] = useState(() => defaultRange(data.maxMonthPerYear, data.years));
  const [picked, setPicked] = useState<Set<string>>(new Set([calc.TOTAL_SERIES]));

  // El inicio nunca queda después del final: el que se mueve arrastra al otro
  const setFrom = (fy: number, fm: number) =>
    setRange(r => order(fy, fm) > order(r.ty, r.tm) ? { fy, fm, ty: fy, tm: fm } : { ...r, fy, fm });
  const setTo = (ty: number, tm: number) =>
    setRange(r => order(ty, tm) < order(r.fy, r.fm) ? { fy: ty, fm: tm, ty, tm } : { ...r, ty, tm });
  const toggleSeries = (name: string) => setPicked(prev => {
    const next = new Set(prev);
    if (next.has(name)) next.delete(name); else next.add(name);
    return next;
  });

  const points = useMemo(
    () => calc.productivitySeries(data, customTimes, { from: { year: range.fy, month: range.fm }, to: { year: range.ty, month: range.tm }, metric, activeEqs }),
    [data, customTimes, range, metric, activeEqs]
  );
  const series = [calc.TOTAL_SERIES].concat(data.equipments);
  const shown = series.filter(s => picked.has(s));
  const colorOf = (name: string) => name === calc.TOTAL_SERIES ? TOTAL_COLOR : SERIES_COLORS[(data.equipments.indexOf(name)) % SERIES_COLORS.length];

  const formatValue = (v: any): string => {
    if (typeof v !== 'number') return '—';
    if (metric === 'utilizacion') return `${v.toFixed(1)}%`;
    if (metric === 'horas') return `${v.toLocaleString('es-AR', { maximumFractionDigits: 0 })} h`;
    return v.toLocaleString('es-AR', { maximumFractionDigits: 0 });
  };
  const axisFormat = (v: any): string => metric === 'utilizacion' ? `${v}%` : Number(v).toLocaleString('es-AR', { maximumFractionDigits: 0 });

  const segmented = (active: boolean) => `px-4 py-1.5 text-xs font-bold rounded-md transition-all ${active ? 'bg-white text-blue-700 shadow-sm border border-blue-100' : 'text-gray-500 hover:text-gray-700'}`;
  const common = { data: points, margin: { top: 10, right: 20, left: 0, bottom: 5 } };
  const axes = [
    <CartesianGrid key="g" strokeDasharray="3 3" vertical={false} />,
    <XAxis key="x" dataKey="label" tick={{ fontSize: 11 }} />,
    <YAxis key="y" tick={{ fontSize: 12 }} tickFormatter={axisFormat} domain={(metric === 'utilizacion' ? [0, (dataMax: number) => Math.max(100, Math.ceil(dataMax / 10) * 10)] : [0, 'auto']) as any} />,
    <Tooltip key="t" contentStyle={{ borderRadius: '12px' }} formatter={(v: any, name: any) => [formatValue(v), name]} />,
    <Legend key="l" />,
  ];
  const objective = metric === 'utilizacion'
    ? <ReferenceLine y={TARGET_UTILIZATION} stroke="#3B82F6" strokeDasharray="5 5" label={{ value: `Objetivo ${TARGET_UTILIZATION} %`, position: 'insideTopRight', fontSize: 11, fill: '#3B82F6' }} />
    : null;

  return (
    <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
      <div className="bg-gray-800 p-5 px-6">
        <h3 className="text-lg font-bold text-white">Evolución de la productividad</h3>
        <p className="text-xs text-gray-400 mt-1">Mes a mes, para el total de la flota activa y los equipos que elijas.</p>
      </div>
      <div className="p-6">
        <div className="flex flex-wrap items-end gap-x-6 gap-y-4 mb-5">
          <div className="flex bg-gray-100 p-1 rounded-lg border border-gray-200">
            <button onClick={() => setKind('lineas')} className={segmented(kind === 'lineas')}>Líneas</button>
            <button onClick={() => setKind('barras')} className={segmented(kind === 'barras')}>Barras</button>
          </div>
          <div>
            <label className="block text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-1">Métrica</label>
            <select value={metric} onChange={e => setMetric(e.target.value as calc.SeriesMetric)} className={selectClass}>
              {METRICS.map(m => <option key={m.id} value={m.id}>{m.label}</option>)}
            </select>
          </div>
          <div className="flex items-end gap-2">
            <div>
              <label className="block text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-1">Año inicio</label>
              <select value={range.fy} onChange={e => setFrom(parseInt(e.target.value), range.fm)} className={selectClass}>
                {data.years.map(y => <option key={y} value={y}>{y}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-1">Mes inicio</label>
              <select value={range.fm} onChange={e => setFrom(range.fy, parseInt(e.target.value))} className={selectClass}>
                {MONTH_NAMES.map((m, i) => <option key={m} value={i}>{m}</option>)}
              </select>
            </div>
          </div>
          <div className="flex items-end gap-2">
            <div>
              <label className="block text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-1">Año final</label>
              <select value={range.ty} onChange={e => setTo(parseInt(e.target.value), range.tm)} className={selectClass}>
                {data.years.map(y => <option key={y} value={y}>{y}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-1">Mes final</label>
              <select value={range.tm} onChange={e => setTo(range.ty, parseInt(e.target.value))} className={selectClass}>
                {MONTH_NAMES.map((m, i) => <option key={m} value={i}>{m}</option>)}
              </select>
            </div>
          </div>
        </div>

        <div className="flex gap-1.5 flex-wrap mb-5">
          {series.map(name => {
            const on = picked.has(name);
            return (
              <button
                key={name}
                onClick={() => toggleSeries(name)}
                className={`px-2.5 py-1.5 text-[10px] font-bold rounded border transition-colors ${on ? 'bg-blue-100 text-blue-800 border-blue-300 shadow-sm' : 'bg-white text-gray-400 border-gray-200 hover:bg-gray-100'}`}
              >
                <span className="inline-block w-2 h-2 rounded-full mr-1.5" style={{ backgroundColor: on ? colorOf(name) : '#D1D5DB' }}></span>{name}
              </button>
            );
          })}
        </div>

        {points.length === 0 || shown.length === 0 ? (
          <div className="text-center p-10 text-gray-500 text-sm">
            {shown.length === 0 ? 'Elegí al menos una serie.' : 'No hay meses con datos cargados en el período elegido.'}
          </div>
        ) : (
          <div className="w-full h-[380px]">
            <ResponsiveContainer width="100%" height="100%">
              {kind === 'lineas' ? (
                <LineChart {...common}>
                  {axes}
                  {objective}
                  {shown.map(name => (
                    <Line key={name} type="monotone" dataKey={name} name={name} stroke={colorOf(name)} strokeWidth={name === calc.TOTAL_SERIES ? 4 : 2} dot={{ r: 3 }} connectNulls={false} />
                  ))}
                </LineChart>
              ) : (
                <BarChart {...common}>
                  {axes}
                  {objective}
                  {shown.map(name => <Bar key={name} dataKey={name} name={name} fill={colorOf(name)} />)}
                </BarChart>
              )}
            </ResponsiveContainer>
          </div>
        )}

        <p className="mt-4 text-[11px] text-gray-400">
          Solo se grafican los meses con datos cargados. El total de la flota activa respeta los equipos tildados en las tablas;
          la utilización del total es horas usadas / horas hábiles de los equipos activos.
          {metric === 'utilizacion' && ` La línea punteada es el objetivo de ${TARGET_UTILIZATION} %.`}
        </p>
      </div>
    </div>
  );
};
