import React, { useState } from "react";
import { AlertCircle, AlertTriangle, CheckCircle2, ChevronDown, ChevronUp } from "lucide-react";
import { DataIssue, QualityReport } from "../data/types";

const formatIso = (iso: string | null): string => {
  if (!iso) return "—";
  const [y, m, d] = iso.split("-");
  return `${d}/${m}/${y}`;
};

const SOURCE_LABEL: Record<string, string> = {
  HORAS: "Horas hábiles",
  HORAS_SL: "Horas hábiles (San Lorenzo)",
  HORAS_AR: "Horas hábiles (Alto Rosario)",
  TIEMPOS: "Tiempos",
  ACUMULADO: "Acumulado",
  AGENDA: "Capacidad de agenda",
  CONTRATOS: "Contratos vigentes",
  CRUCE: "Cruce de hojas",
};

const SEVERITY_STYLE: Record<string, string> = {
  error: "bg-red-50 text-red-700 border-red-200",
  warning: "bg-amber-50 text-amber-700 border-amber-200",
  info: "bg-blue-50 text-blue-700 border-blue-200",
};
const SEVERITY_LABEL: Record<string, string> = { error: "Error", warning: "Aviso", info: "Info" };

const IssueRow: React.FC<{ issue: DataIssue }> = ({ issue }) => (
  <li className="py-2.5 flex gap-3 items-start">
    <span className={`shrink-0 text-[10px] font-black uppercase px-2 py-0.5 rounded border ${SEVERITY_STYLE[issue.severity]}`}>
      {SEVERITY_LABEL[issue.severity]}
    </span>
    <div className="min-w-0">
      <p className="text-sm text-gray-700">
        <span className="font-bold text-gray-500 text-[10px] uppercase mr-2">{SOURCE_LABEL[issue.source]}</span>
        {issue.message}
        {issue.count > 1 && <span className="font-bold text-gray-500"> ({issue.count})</span>}
      </p>
      {issue.examples.length > 0 && (
        <p className="text-xs text-gray-400 mt-0.5 break-words">Ej.: {issue.examples.join(" · ")}</p>
      )}
    </div>
  </li>
);

export const DataQualityPanel: React.FC<{ report: QualityReport }> = ({ report }) => {
  const [open, setOpen] = useState(report.status === "errors");
  const { summary } = report;
  const problems = report.issues.filter((i) => i.severity !== "info").length;

  const icon =
    report.status === "errors" ? <AlertCircle size={18} className="text-red-500" /> :
    report.status === "warnings" ? <AlertTriangle size={18} className="text-amber-500" /> :
    <CheckCircle2 size={18} className="text-emerald-500" />;

  return (
    <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden mb-6 print:hidden">
      <button
        type="button"
        onClick={() => setOpen(!open)}
        className="w-full p-4 flex items-center justify-between gap-4 text-left hover:bg-gray-50/50 transition-colors"
      >
        <div className="flex items-center gap-3 min-w-0">
          <div className="shrink-0">{icon}</div>
          <div className="min-w-0">
            <h3 className="text-sm font-bold text-gray-800">Calidad de datos</h3>
            <p className="text-xs text-gray-500 truncate">
              {summary.validRows.toLocaleString("es-AR")} estudios leídos
              {summary.discardedRows > 0 && ` · ${summary.discardedRows.toLocaleString("es-AR")} descartados`}
              {summary.maxDate && ` · último dato: ${formatIso(summary.maxDate)}`}
              {` · ${problems === 0 ? "sin observaciones" : `${problems} observación${problems === 1 ? "" : "es"}`}`}
            </p>
          </div>
        </div>
        <div className="shrink-0 p-1.5 rounded-full bg-white border border-gray-200 shadow-sm">
          {open ? <ChevronUp size={18} className="text-gray-600" /> : <ChevronDown size={18} className="text-gray-600" />}
        </div>
      </button>
      {open && (
        <div className="px-5 pb-4 border-t border-gray-100">
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 py-4 text-xs">
            <div><span className="block font-bold text-gray-400 uppercase text-[10px]">Período</span><span className="font-bold text-gray-700">{formatIso(summary.minDate)} a {formatIso(summary.maxDate)}</span></div>
            <div><span className="block font-bold text-gray-400 uppercase text-[10px]">Equipos / estudios</span><span className="font-bold text-gray-700">{summary.equipments} / {summary.studies}</span></div>
            <div><span className="block font-bold text-gray-400 uppercase text-[10px]">Filas leídas / válidas</span><span className="font-bold text-gray-700">{summary.totalRows.toLocaleString("es-AR")} / {summary.validRows.toLocaleString("es-AR")}</span></div>
            <div><span className="block font-bold text-gray-400 uppercase text-[10px]">Con tiempo por defecto</span><span className="font-bold text-gray-700">{summary.defaultTimeShare.toFixed(1)}% del volumen</span></div>
          </div>
          {report.issues.length === 0 ? (
            <p className="text-sm text-gray-500">No se encontraron observaciones.</p>
          ) : (
            <ul className="divide-y divide-gray-100">
              {report.issues.map((issue) => <IssueRow key={issue.source + issue.code} issue={issue} />)}
            </ul>
          )}
        </div>
      )}
    </div>
  );
};
