import React from "react";
import { Target } from "lucide-react";
import { TARGET_UTILIZATION } from "../config";
import * as calc from "../calc";
import { SemaforoLegend } from "./Legends";
import type { MonthlyDetailRequest } from "./MonthlyDetailModal";

const formatGap = (gap: number) => `${gap > 0 ? '+' : ''}${gap.toFixed(1)} %`;
const formatCount = (n: number) => n.toLocaleString('es-AR', { maximumFractionDigits: 0 });
const formatUsd = (n: number, decimals: number = 0) => `USD ${n.toLocaleString('es-AR', { minimumFractionDigits: decimals, maximumFractionDigits: decimals })}`;
const formatSigned = (n: number) => `${Math.round(n) > 0 ? '+' : ''}${formatCount(n)}`;

// Valor de la tabla que abre una ventana con el detalle mes a mes
const CLICKABLE = "cursor-pointer underline decoration-dotted underline-offset-4 hover:decoration-solid focus:outline-none";

interface FleetTableProps {
  title: string;
  /** Color del ícono del título (clase de Tailwind). */
  iconClass?: string;
  /** Período considerado, p. ej. "Enero – Julio 2026 · 7 meses". */
  period: string;
  /** Encabezado de la columna de utilización. */
  utilHeader: string;
  totalLabel: string;
  /** Equipos de la tabla (el llamador deja afuera los que no corresponde mostrar) y su total. */
  fleet: calc.FleetSummary;
  /** Si se pasa, agrega la columna "Utilización Original" (situación sin simular). */
  baseline?: calc.FleetSummary;
  /** Equipos fuera de servicio en el escenario: se muestran atenuados, sin cifras. */
  removed?: string[];
  /** Si se pasa, agrega las columnas de cobertura de agenda y utilización efectiva de agenda. */
  agenda?: calc.AgendaSummary;
  /** Si se pasa, agrega el contrato mensual (USD) y el costo de mantenimiento por estudio. */
  contracts?: calc.ContractSummary;
  /** Si se pasa, el valor de utilización efectiva de agenda abre la distribución por categoría. */
  onAgendaDetail?: (eq: string | null) => void;
  /** Agenda de la situación sin simular: junto a cada valor de agenda se muestra la diferencia contra ella. */
  agendaBaseline?: calc.AgendaSummary;
  /** Si se pasa, cada equipo tiene una casilla para sacarlo del total. */
  onToggleEq?: (eq: string) => void;
  onDetail: (request: MonthlyDetailRequest) => void;
  /**
   * Qué columnas se muestran: todas (por defecto) o sólo las de un grupo de la pestaña Resumen
   * (productividad, agenda o costos).
   */
  group?: 'all' | 'productividad' | 'agenda' | 'costos';
  /** Encabezado de la columna de estudios totales (según el período elegido). */
  studiesHeader?: string;
  /** Etiquetas extra junto a la leyenda del semáforo. */
  badges?: React.ReactNode;
  footnote: React.ReactNode;
}

/**
 * Tabla de utilización promedio por equipo: color por semáforo institucional, composición por categoría,
 * brecha contra el objetivo, estudios y estudios objetivo. La usan la vista 1 y el simulador.
 */
export const FleetTable: React.FC<FleetTableProps> = ({
  title, iconClass = 'text-emerald-400', period, utilHeader, totalLabel, fleet, baseline, agenda, agendaBaseline, contracts, onAgendaDetail, removed = [], onToggleEq, onDetail, group = 'all', studiesHeader = 'Estudios Totales en el Año', badges, footnote,
}) => {
  const showProd = group === 'all' || group === 'productividad';
  // Agenda: cobertura, utilización efectiva y (en el detalle de agenda) las horas en cantidades. En el grupo de
  // productividad solo se muestra la utilización efectiva.
  const showAgenda = !!agenda && (group === 'all' || group === 'agenda');
  const showEffective = !!agenda && (group === 'all' || group === 'agenda' || group === 'productividad');
  const showAgendaHours = !!agenda && group === 'agenda';
  const showContracts = !!contracts && (group === 'all' || group === 'costos');
  const showComposition = !agenda && showProd;
  const total = fleet.total;
  const baseRow = (eq: string | null): calc.FleetRow | undefined =>
    !baseline ? undefined : (eq === null ? baseline.total : baseline.rows.filter(r => r.eq === eq)[0]);
  const sideBorder = "border-l border-gray-100";
  // Columnas después del nombre del equipo (para el texto de los equipos fuera de servicio). Con agenda, la
  // composición por categoría ya no es una columna: se ve al hacer clic en la utilización efectiva.
  const columns = (agenda ? 9 : 8) + (baseline ? 1 : 0) + (contracts ? 2 : 0);

  const agendaStat = (eq: string | null): calc.AgendaStat | undefined =>
    !agenda ? undefined : (eq === null ? agenda.total : agenda.rows.filter(r => r.label === eq)[0]);
  const agendaBaseStat = (eq: string | null): calc.AgendaStat | undefined =>
    !agendaBaseline ? undefined : (eq === null ? agendaBaseline.total : agendaBaseline.rows.filter(r => r.label === eq)[0]);
  // Diferencia contra la situación original (se omite si no cambia)
  const agendaDelta = (now: number | null, before: number | null | undefined) =>
    now === null || before === null || before === undefined || Math.abs(now - before) < 0.05
      ? null
      : <div className="text-[10px] font-bold text-gray-400 mt-0.5">{formatGap(now - before)} vs original</div>;

  // Cobertura de agenda (sin color) y utilización efectiva de agenda (con el semáforo de la utilización)
  const agendaCells = (eq: string | null, strong: boolean) => {
    const st = agendaStat(eq);
    const base = agendaBaseStat(eq);
    const empty = <span className="text-gray-300 font-bold" title="Sin datos de agenda en los meses considerados">—</span>;
    const size = strong ? 'text-base font-black' : 'text-sm font-bold';
    const hoursCell = (hours: number | undefined, before: number | undefined, title: string) => (
      <td className="px-6 py-4 text-center">
        {st && st.months > 0 && hours !== undefined
          ? <span className={`${size} text-gray-700`} title={title}>{formatCount(hours)} h</span>
          : empty}
        {st && st.months > 0 && hours !== undefined && before !== undefined && Math.abs(hours - before) >= 0.5
          ? <div className="text-[10px] font-bold text-gray-400 mt-0.5">{formatSigned(hours - before)} h vs original</div>
          : null}
      </td>
    );
    return (
      <>
        {showAgendaHours && hoursCell(st && st.potentialHours, base && base.potentialHours, 'Horas hábiles (clínica abierta) de los meses con agenda cargada')}
        {showAgendaHours && hoursCell(st && st.agendaHours, base && base.agendaHours, 'Horas de agenda abierta de los meses con agenda cargada (limitadas a las horas hábiles)')}
        {showAgenda && <td className="px-6 py-4 text-center">
          {st && st.coverage !== null
            ? <span className={`${size} text-gray-700`} title={`${formatCount(st.agendaHours)} h de agenda sobre ${formatCount(st.potentialHours)} h de clínica abierta`}>{st.coverage.toFixed(1)}%</span>
            : empty}
          {st && agendaDelta(st.coverage, base && base.coverage)}
        </td>}
        {showEffective && <td className="px-6 py-4 text-center">
          {st && st.effective !== null
            ? (onAgendaDetail
              ? <button
                  onClick={() => onAgendaDetail(eq)}
                  title="Ver cómo se reparte la agenda por categoría"
                  className={`${size} ${CLICKABLE}`}
                  style={{ color: calc.utilizationColor(st.effective) }}
                >{st.effective.toFixed(1)}%</button>
              : <span className={size} style={{ color: calc.utilizationColor(st.effective) }} title={`${formatCount(st.usedHours)} h de adquisición sobre ${formatCount(st.agendaHours)} h de agenda`}>{st.effective.toFixed(1)}%</span>)
            : empty}
          {st && agendaDelta(st.effective, base && base.effective)}
        </td>}
      </>
    );
  };

  // Estudios objetivo y diferencia con lo realizado. Con la hoja de agenda cargada el objetivo se plantea sobre las
  // horas de agenda abierta (sólo los meses con agenda); sin ella, sobre las horas hábiles de la clínica.
  const targetCells = (row: calc.FleetRow, eq: string | null, strong: boolean, border: string) => {
    const size = strong ? 'text-base font-black' : 'text-sm font-bold';
    const st = agendaStat(eq);
    const empty = <span className="text-gray-300 font-bold" title={agenda
      ? 'Sin agenda cargada (o sin estudios) en los meses considerados: no se puede plantear el objetivo'
      : 'Sin estudios en los meses considerados: no hay mezcla para estimar el objetivo'}>—</span>;
    const target = agenda ? (st ? st.targetStudies : null) : row.targetStudies;
    const gap = agenda ? (st ? st.studyGap : null) : row.studyGap;
    const minutes = agenda ? (st && st.studies > 0 ? (st.usedHours * 60) / st.studies : null) : row.avgMinutes;
    const targetTitle = !strong && minutes !== null ? `${minutes.toFixed(1)} min promedio por estudio con la mezcla del período` : undefined;
    const gapTitle = agenda && st ? `Realizados en los ${st.months} ${st.months === 1 ? 'mes' : 'meses'} con agenda: ${formatCount(st.studies)}` : undefined;
    return (
      <>
        <td className={`px-6 py-4 text-center ${border}`}>
          {target !== null ? <span className={`${size} text-blue-700`} title={targetTitle}>{formatCount(target)}</span> : empty}
        </td>
        <td className="px-6 py-4 text-center">
          {gap !== null ? <span className={`${size} text-gray-600`} title={gapTitle}>{formatSigned(gap)}</span> : empty}
        </td>
      </>
    );
  };

  // Contrato mensual (USD) y costo de mantenimiento por estudio hecho
  const contractCells = (eq: string | null, strong: boolean, border: string) => {
    const c = !contracts ? undefined : (eq === null ? contracts.total : contracts.rows.filter(r => r.label === eq)[0]);
    const size = strong ? 'text-base font-black' : 'text-sm font-bold';
    const empty = <span className="text-gray-300 font-bold" title="Sin contrato cargado para este equipo">—</span>;
    const incomplete = c && !c.complete;
    const note = incomplete ? ' · Incluye solo la parte en USD: falta la cotización para convertir la parte en pesos.' : '';
    return (
      <>
        <td className={`px-6 py-4 text-center ${border}`}>
          {c && c.monthlyUsd !== null
            ? <span
                className={`${size} text-gray-700`}
                title={`${c.coverage ? `Cobertura: ${c.coverage} · ` : ''}Acumulado en ${c.months} ${c.months === 1 ? 'mes' : 'meses'}: ${formatUsd(c.accumulatedUsd || 0)}${note}`}
              >{formatUsd(c.monthlyUsd)}{incomplete ? '*' : ''}</span>
            : empty}
        </td>
        <td className="px-6 py-4 text-center">
          {c && c.perStudyUsd !== null
            ? <span className={`${size} text-gray-700`} title={`${formatUsd(c.accumulatedUsd || 0)} acumulados / ${formatCount(c.studies)} estudios${note}`}>{formatUsd(c.perStudyUsd, 2)}{incomplete ? '*' : ''}</span>
            : empty}
        </td>
      </>
    );
  };

  const utilCell = (row: calc.FleetRow, eq: string | null, big: boolean) => {
    const base = baseRow(eq);
    const delta = base ? row.util - base.util : null;
    return (
      <>
        <button
          onClick={() => onDetail({ kind: 'util', eq })}
          title="Ver la utilización mes a mes"
          className={`${big ? 'text-xl' : 'text-lg'} font-black ${CLICKABLE}`}
          style={{ color: calc.utilizationColor(row.util) }}
        >
          {row.util.toFixed(1)}%
        </button>
        {delta !== null && <div className="text-[10px] font-bold text-gray-400 mt-0.5">{formatGap(delta)} vs original</div>}
      </>
    );
  };

  const composition = (row: calc.FleetRow, strong: boolean) => (
    <div className={`${strong ? 'text-sm font-black' : 'text-xs font-bold'} space-y-1`}>
      <div className="flex justify-between items-center"><span className={`${strong ? 'text-blue-700' : 'text-blue-600'} uppercase`}>Neuro</span> <span>{row.pct.Neuro.toFixed(1)}%</span></div>
      <div className="flex justify-between items-center"><span className={`${strong ? 'text-emerald-700' : 'text-emerald-600'} uppercase`}>Cuerpo</span> <span>{row.pct.Cuerpo.toFixed(1)}%</span></div>
      <div className="flex justify-between items-center"><span className={`${strong ? 'text-amber-700' : 'text-amber-600'} uppercase`}>Commodities</span> <span>{row.pct.Commodities.toFixed(1)}%</span></div>
    </div>
  );

  return (
    <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
      <div className="bg-gray-800 p-5 px-6 flex flex-wrap items-center justify-between gap-3">
        <div>
          <h3 className="text-lg font-bold text-white flex items-center gap-2">
            <Target className={iconClass} size={20}/> {title}
          </h3>
          {period && <p className="text-xs text-gray-400 mt-1">Acumulado: {period}</p>}
        </div>
        <div className="flex items-center gap-3">
          {badges}
          <SemaforoLegend />
        </div>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full text-sm text-left">
          <thead className="text-[10px] text-gray-500 uppercase bg-gray-50 border-b border-gray-200">
            <tr>
              <th className="px-6 py-4 font-bold w-[250px]">Equipo de Resonancia</th>
              {baseline && showProd && <th className="px-6 py-4 text-center font-bold">Utilización Original</th>}
              {showProd && <th className="px-6 py-4 text-center font-bold">{utilHeader}</th>}
              {showAgendaHours && <th className="px-6 py-4 text-center font-bold">Horas Hábiles (Clínica Abierta)</th>}
              {showAgendaHours && <th className="px-6 py-4 text-center font-bold">Horas de Agenda Abierta</th>}
              {showAgenda && <th className="px-6 py-4 text-center font-bold">Cobertura de Agenda</th>}
              {showEffective && <th className="px-6 py-4 text-center font-bold">Utilización Efectiva de Agenda</th>}
              {showComposition && <th className="px-6 py-4 font-bold border-l border-gray-100 min-w-[200px]">Composición (% Hs Hábiles)</th>}
              {showProd && <>
              <th className="px-6 py-4 text-center font-bold border-l border-gray-100 text-blue-700">Objetivo Fijo</th>
              <th className="px-6 py-4 text-center font-bold border-l border-gray-100">Brecha vs Objetivo</th>
              <th className="px-6 py-4 text-center font-bold border-l border-gray-100">Estudios Promedio por Mes</th>
              <th className="px-6 py-4 text-center font-bold">{studiesHeader}</th>
              <th className="px-6 py-4 text-center font-bold border-l border-gray-100 text-blue-700">Estudios Objetivo ({TARGET_UTILIZATION} %{agenda ? ' de la agenda' : ''})</th>
              <th className="px-6 py-4 text-center font-bold">Diferencia vs Objetivo (Estudios)</th>
              </>}
              {showContracts && <th className="px-6 py-4 text-center font-bold border-l border-gray-100">Contrato Mensual (USD)</th>}
              {showContracts && <th className="px-6 py-4 text-center font-bold">Mantenimiento por Estudio (USD)</th>}
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
            {fleet.rows.map(row => {
              const base = baseRow(row.eq);
              return (
                <tr key={row.eq} className={`transition-colors ${row.isActive ? 'hover:bg-gray-50' : 'bg-gray-50 opacity-40 grayscale'}`}>
                  <td className="px-6 py-4">
                    {onToggleEq ? (
                      <label className="flex items-center gap-3 cursor-pointer">
                        <input type="checkbox" checked={row.isActive} onChange={() => onToggleEq(row.eq)} className="w-4 h-4 text-blue-600 rounded focus:ring-blue-500 cursor-pointer"/>
                        <span className="font-bold text-gray-800 text-xs">{row.eq}</span>
                      </label>
                    ) : (
                      <span className="font-bold text-gray-800 text-xs">{row.eq}</span>
                    )}
                  </td>
                  {baseline && showProd && (
                    <td className="px-6 py-4 text-center">
                      {base && <span className="text-sm font-bold" style={{ color: calc.utilizationColor(base.util) }}>{base.util.toFixed(1)}%</span>}
                    </td>
                  )}
                  {showProd && <td className="px-6 py-4 text-center">{utilCell(row, row.eq, false)}</td>}
                  {showEffective && agendaCells(row.eq, false)}
                  {showComposition && <td className={`px-6 py-3 ${sideBorder}`}>{composition(row, false)}</td>}
                  {showProd && <>
                  <td className={`px-6 py-4 text-center ${sideBorder}`}>
                    <span className="text-blue-700 font-bold bg-blue-50 px-3 py-1 rounded text-xs">{TARGET_UTILIZATION.toFixed(1)}%</span>
                  </td>
                  <td className={`px-6 py-4 text-center ${sideBorder}`}>
                    <span className="text-sm font-bold text-gray-600">{formatGap(row.gap)}</span>
                  </td>
                  <td className={`px-6 py-4 text-center ${sideBorder}`}>
                    <button
                      onClick={() => onDetail({ kind: 'studies', eq: row.eq })}
                      title="Ver los estudios mes a mes"
                      className={`text-sm font-bold text-gray-800 ${CLICKABLE}`}
                    >
                      {formatCount(row.avgStudiesPerMonth)}
                    </button>
                  </td>
                  <td className="px-6 py-4 text-center">
                    <span className="text-sm font-bold text-gray-600">{formatCount(row.studies)}</span>
                  </td>
                  {targetCells(row, row.eq, false, sideBorder)}
                  </>}
                  {showContracts && contractCells(row.eq, false, sideBorder)}
                </tr>
              );
            })}
            {removed.map(eq => (
              <tr key={eq} className="bg-gray-50">
                <td className="px-6 py-4">
                  <span className="font-bold text-gray-400 text-xs line-through">{eq}</span>
                </td>
                <td colSpan={columns} className="px-6 py-4 text-[10px] font-bold uppercase tracking-wider text-red-400">
                  Fuera de servicio en este escenario: sus estudios se reparten entre los demás equipos
                </td>
              </tr>
            ))}
            <tr className="bg-gray-100 border-t-2 border-gray-300">
              <td className="px-6 py-4 font-black text-gray-800 text-xs uppercase tracking-widest pl-12">
                {totalLabel}
              </td>
              {baseline && showProd && (
                <td className="px-6 py-4 text-center">
                  <span className="text-base font-black" style={{ color: calc.utilizationColor(baseline.total.util) }}>{baseline.total.util.toFixed(1)}%</span>
                </td>
              )}
              {showProd && <td className="px-6 py-4 text-center">{utilCell(total, null, true)}</td>}
              {showEffective && agendaCells(null, true)}
              {showComposition && <td className="px-6 py-3 border-l border-gray-200">{composition(total, true)}</td>}
              {showProd && <>
              <td className="px-6 py-4 text-center border-l border-gray-200">
                <span className="text-blue-800 font-black bg-blue-100 px-3 py-1 rounded text-xs">{TARGET_UTILIZATION.toFixed(1)}%</span>
              </td>
              <td className="px-6 py-4 text-center border-l border-gray-200">
                <span className="text-base font-black text-gray-700">{formatGap(total.gap)}</span>
              </td>
              <td className="px-6 py-4 text-center border-l border-gray-200">
                <button
                  onClick={() => onDetail({ kind: 'studies', eq: null })}
                  title="Ver los estudios de la flota mes a mes"
                  className={`text-base font-black text-gray-800 ${CLICKABLE}`}
                >
                  {formatCount(total.avgStudiesPerMonth)}
                </button>
              </td>
              <td className="px-6 py-4 text-center">
                <span className="text-base font-black text-gray-700">{formatCount(total.studies)}</span>
              </td>
              {targetCells(total, null, true, 'border-l border-gray-200')}
              </>}
              {showContracts && contractCells(null, true, 'border-l border-gray-200')}
            </tr>
          </tbody>
        </table>
      </div>
      <p className="px-6 py-3 text-[11px] text-gray-400 border-t border-gray-100">{footnote}</p>
    </div>
  );
};
