import React from "react";
import { PieChart, X } from "lucide-react";
import * as calc from "../calc";

const formatCount = (n: number) => n.toLocaleString('es-AR', { maximumFractionDigits: 0 });
const formatHours = (n: number) => n.toLocaleString('es-AR', { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const formatPct = (n: number) => `${n.toFixed(1)}%`;

const CATEGORY_STYLE: Record<string, { bar: string; text: string }> = {
  Neuro: { bar: 'bg-blue-600', text: 'text-blue-700' },
  Cuerpo: { bar: 'bg-emerald-500', text: 'text-emerald-700' },
  Commodities: { bar: 'bg-amber-500', text: 'text-amber-700' },
  Otros: { bar: 'bg-gray-400', text: 'text-gray-600' },
};

interface AgendaCompositionModalProps {
  /** Indicadores de agenda del equipo (o del total) que se está detallando; undefined = ventana cerrada. */
  stat: calc.AgendaStat | undefined;
  /** Equipo, o el nombre del total cuando se detalla la flota. */
  name: string;
  year: number;
  onClose: () => void;
  /** Aclaración del título, p. ej. "escenario simulado". */
  scenarioLabel?: string;
}

/**
 * Ventana que se abre al hacer clic en la utilización efectiva de agenda: cómo se reparte entre las
 * categorías principales el tiempo de la agenda abierta (y cuánto de la agenda queda sin usar).
 */
export const AgendaCompositionModal: React.FC<AgendaCompositionModalProps> = ({ stat, name, year, onClose, scenarioLabel }) => {
  if (!stat) return null;

  const agenda = stat.agendaHours;
  const used = stat.usedHours;
  const unused = Math.max(agenda - used, 0);
  // Base de las barras: la agenda, o lo usado si la agenda no alcanzó (utilización efectiva > 100 %)
  const base = Math.max(agenda, used);
  const categories = (['Neuro', 'Cuerpo', 'Commodities', 'Otros'] as calc.MainCategory[])
    .filter(c => c !== 'Otros' || stat.hoursByCategory.Otros > 0);

  const th = "px-4 py-3 text-center font-bold";
  const td = "px-4 py-2.5 text-center";
  const pctOf = (n: number, d: number) => (d > 0 ? (n / d) * 100 : 0);

  return (
    <div className="fixed inset-0 z-[120] bg-gray-900/70 backdrop-blur-sm flex items-center justify-center p-4 animate-in fade-in duration-200">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-3xl max-h-[90vh] flex flex-col overflow-hidden animate-in zoom-in-95 duration-200">
        <div className="bg-gray-800 px-6 py-4 flex justify-between items-center shrink-0">
          <h3 className="text-lg font-bold text-white flex items-center gap-2">
            <PieChart size={20} className="text-blue-400" />
            Distribución de la agenda por categoría · {name}{scenarioLabel ? ` (${scenarioLabel})` : ''}
          </h3>
          <button onClick={onClose} className="text-gray-400 hover:text-white transition-colors p-1 bg-gray-700/50 rounded-lg"><X size={20} /></button>
        </div>
        <div className="bg-gray-100 px-6 py-2 border-b border-gray-200 text-xs font-bold text-gray-500 uppercase tracking-wider shrink-0">
          {year} · Utilización efectiva de agenda: {stat.effective === null ? '—' : formatPct(stat.effective)} · {formatCount(agenda)} h de agenda en {stat.months} {stat.months === 1 ? 'mes' : 'meses'}
        </div>
        <div className="p-6 overflow-y-auto">
          {agenda <= 0 ? (
            <p className="text-center text-gray-500 p-8">No hay agenda cargada en los meses considerados.</p>
          ) : (
            <>
              <p className="text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2">Cómo se usó la agenda abierta</p>
              <div className="flex h-6 rounded-lg overflow-hidden bg-gray-200 shadow-inner">
                {categories.map(c => (
                  <div
                    key={c}
                    className={CATEGORY_STYLE[c].bar}
                    style={{ width: `${pctOf(stat.hoursByCategory[c], base)}%` }}
                    title={`${c}: ${formatHours(stat.hoursByCategory[c])} h (${formatPct(pctOf(stat.hoursByCategory[c], agenda))} de la agenda)`}
                  />
                ))}
              </div>
              <div className="flex flex-wrap gap-4 mt-2 text-[10px] font-bold text-gray-500 uppercase">
                {categories.map(c => (
                  <span key={c} className="flex items-center gap-1.5"><span className={`w-2.5 h-2.5 rounded ${CATEGORY_STYLE[c].bar}`}></span>{c}</span>
                ))}
                <span className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded bg-gray-200 border border-gray-300"></span>Agenda sin usar</span>
              </div>

              <div className="mt-6 border border-gray-200 rounded-xl overflow-hidden">
                <table className="w-full text-sm">
                  <thead className="text-[10px] text-gray-500 uppercase bg-gray-50 border-b border-gray-200">
                    <tr>
                      <th className={`${th} text-left`}>Categoría</th>
                      <th className={th}>Horas Usadas</th>
                      <th className={th}>% de la Agenda</th>
                      <th className={th}>% de lo Usado</th>
                      <th className={th}>Estudios</th>
                      <th className={th}>% de Estudios</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-100">
                    {categories.map(c => (
                      <tr key={c}>
                        <td className={`${td} text-left font-bold uppercase text-xs ${CATEGORY_STYLE[c].text}`}>{c}</td>
                        <td className={td}>{formatHours(stat.hoursByCategory[c])}</td>
                        <td className={`${td} font-bold`}>{formatPct(pctOf(stat.hoursByCategory[c], agenda))}</td>
                        <td className={td}>{formatPct(pctOf(stat.hoursByCategory[c], used))}</td>
                        <td className={td}>{formatCount(stat.studiesByCategory[c])}</td>
                        <td className={td}>{formatPct(pctOf(stat.studiesByCategory[c], stat.studies))}</td>
                      </tr>
                    ))}
                    <tr className="text-gray-400">
                      <td className={`${td} text-left font-bold uppercase text-xs`}>Agenda sin usar</td>
                      <td className={td}>{formatHours(unused)}</td>
                      <td className={td}>{formatPct(pctOf(unused, agenda))}</td>
                      <td className={td}>—</td>
                      <td className={td}>—</td>
                      <td className={td}>—</td>
                    </tr>
                    <tr className="bg-gray-100 border-t-2 border-gray-300 font-black text-gray-800">
                      <td className={`${td} text-left uppercase text-xs`}>Total</td>
                      <td className={td}>{formatHours(used)} de {formatHours(agenda)}</td>
                      <td className={td}>
                        <span style={{ color: calc.utilizationColor(pctOf(used, agenda)) }}>{formatPct(pctOf(used, agenda))}</span>
                      </td>
                      <td className={td}>{formatPct(100)}</td>
                      <td className={td}>{formatCount(stat.studies)}</td>
                      <td className={td}>{formatPct(100)}</td>
                    </tr>
                  </tbody>
                </table>
              </div>
              <p className="mt-3 text-[11px] text-gray-400">
                Horas y estudios de los meses seleccionados que tienen agenda cargada (la agenda de cada mes se limita a las horas hábiles).
                "% de la agenda" suma la utilización efectiva; "% de lo usado" es la mezcla de categorías entre los estudios realizados.
                {used > agenda + 1e-9 && ' La carga supera la agenda abierta: las barras se muestran sobre las horas usadas.'}
              </p>
            </>
          )}
        </div>
      </div>
    </div>
  );
};
