import React from "react";
import { BarChart2, X } from "lucide-react";
import { Bar, BarChart, CartesianGrid, Cell, ReferenceLine, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { TARGET_UTILIZATION } from "../config";
import * as calc from "../calc";

const EXCLUDED_COLOR = "#D1D5DB";
const STUDIES_COLOR = "#3B82F6";
const TARGET_COLOR = "#BFDBFE";
const formatCount = (n: number) => n.toLocaleString('es-AR', { maximumFractionDigits: 0 });
const formatSigned = (n: number) => `${Math.round(n) > 0 ? '+' : ''}${formatCount(n)}`;
const formatHours = (n: number) => n.toLocaleString('es-AR', { minimumFractionDigits: 1, maximumFractionDigits: 1 });

export interface MonthlyDetailRequest {
  kind: 'util' | 'studies';
  /** Equipo, o null para el total de la flota. */
  eq: string | null;
}

interface MonthlyDetailModalProps {
  detail: MonthlyDetailRequest | null;
  onClose: () => void;
  /** Detalle de los 12 meses (el componente muestra sólo los que tienen datos). */
  months: calc.FleetMonthDetail[];
  /** Fila de la tabla del equipo (o del total) que se está detallando. */
  summary: calc.FleetRow | undefined;
  year: number;
  /**
   * Objetivo de estudios del equipo (o del total) y su diferencia con lo realizado; `basis` indica sobre qué horas
   * se planteó (agenda abierta u horas hábiles de la clínica).
   */
  targetSummary?: { target: number | null; gap: number | null; basis: calc.TargetBasis };
  /** Nombre que se muestra cuando se detalla el total. */
  totalLabel: string;
  /** Aclaración del título, p. ej. "escenario simulado". */
  scenarioLabel?: string;
}

/**
 * Ventana de las tablas de flota: utilización mes a mes o estudios mes a mes de un equipo
 * (o del total de la flota). Los meses fuera de la selección se muestran en gris y no cuentan.
 */
export const MonthlyDetailModal: React.FC<MonthlyDetailModalProps> = ({ detail, onClose, months, summary, targetSummary, year, totalLabel, scenarioLabel }) => {
  if (!detail) return null;

  const isUtil = detail.kind === 'util';
  const name = detail.eq === null ? totalLabel : detail.eq;
  const rows = months.filter(r => r.hasData);
  const included = rows.filter(r => r.included);
  const average = summary ? summary.avgStudiesPerMonth : 0;
  const targetTotal = targetSummary ? targetSummary.target : null;
  const basisLabel = targetSummary && targetSummary.basis === 'agenda' ? ' de la agenda' : '';

  const chartData = rows.map(r => ({
    mes: r.mes.substring(0, 3),
    value: isUtil ? r.util : r.studies,
    target: r.targetStudies === null ? undefined : r.targetStudies,
    color: !r.included ? EXCLUDED_COLOR : (isUtil ? calc.utilizationColor(r.util) : STUDIES_COLOR),
  }));

  const th = "px-4 py-3 text-center font-bold";
  const td = "px-4 py-2.5 text-center";

  return (
    <div className="fixed inset-0 z-[120] bg-gray-900/70 backdrop-blur-sm flex items-center justify-center p-4 animate-in fade-in duration-200">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-3xl max-h-[90vh] flex flex-col overflow-hidden animate-in zoom-in-95 duration-200">
        <div className="bg-gray-800 px-6 py-4 flex justify-between items-center shrink-0">
          <h3 className="text-lg font-bold text-white flex items-center gap-2">
            <BarChart2 size={20} className="text-blue-400" />
            {isUtil ? 'Utilización mes a mes' : 'Estudios mes a mes'} · {name}{scenarioLabel ? ` (${scenarioLabel})` : ''}
          </h3>
          <button onClick={onClose} className="text-gray-400 hover:text-white transition-colors p-1 bg-gray-700/50 rounded-lg"><X size={20} /></button>
        </div>
        <div className="bg-gray-100 px-6 py-2 border-b border-gray-200 text-xs font-bold text-gray-500 uppercase tracking-wider shrink-0">
          {year} · {isUtil
            ? `Utilización promedio anual: ${summary ? summary.util.toFixed(1) : '0.0'}%`
            : `Promedio: ${formatCount(average)} estudios por mes${targetTotal !== null ? ` · Objetivo (${TARGET_UTILIZATION} %${basisLabel}): ${formatCount(targetTotal / Math.max(included.length, 1))} por mes` : ''}`}
        </div>
        <div className="p-6 overflow-y-auto">
          {rows.length === 0 ? (
            <p className="text-center text-gray-500 p-8">No hay meses con datos en este año.</p>
          ) : (
            <>
              <div className="w-full h-[260px]">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={chartData}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} />
                    <XAxis dataKey="mes" tick={{ fontSize: 12 }} />
                    <YAxis
                      tick={{ fontSize: 12 }}
                      tickFormatter={(v: any) => (isUtil ? `${v}%` : formatCount(v))}
                      domain={isUtil ? [0, (dataMax: number) => Math.max(100, Math.ceil(dataMax / 10) * 10)] : [0, 'auto']}
                    />
                    <Tooltip
                      contentStyle={{ borderRadius: '12px' }}
                      formatter={(value: any, name: any) => [isUtil ? `${Number(value).toFixed(1)}%` : formatCount(Number(value)), isUtil ? 'Utilización' : name]}
                    />
                    {isUtil
                      ? <ReferenceLine y={TARGET_UTILIZATION} stroke="#2563EB" strokeDasharray="5 5" label={{ value: `Objetivo ${TARGET_UTILIZATION}%`, position: 'insideTopRight', fontSize: 11, fill: '#2563EB' }} />
                      : <ReferenceLine y={average} stroke="#2563EB" strokeDasharray="5 5" label={{ value: 'Promedio', position: 'insideTopRight', fontSize: 11, fill: '#2563EB' }} />}
                    <Bar dataKey="value" name="Estudios" barSize={isUtil ? 28 : 18} radius={[4, 4, 0, 0]}>
                      {chartData.map((e, i) => <Cell key={i} fill={e.color} />)}
                    </Bar>
                    {!isUtil && <Bar dataKey="target" name={`Objetivo (${TARGET_UTILIZATION} %)`} fill={TARGET_COLOR} barSize={18} radius={[4, 4, 0, 0]} />}
                  </BarChart>
                </ResponsiveContainer>
              </div>

              <div className="mt-6 border border-gray-200 rounded-xl overflow-hidden">
                <table className="w-full text-sm">
                  <thead className="text-[10px] text-gray-500 uppercase bg-gray-50 border-b border-gray-200">
                    {isUtil ? (
                      <tr>
                        <th className={`${th} text-left`}>Mes</th>
                        <th className={th}>Horas Hábiles</th>
                        <th className={th}>Horas Usadas</th>
                        <th className={th}>Utilización</th>
                        <th className={th}>Estudios</th>
                      </tr>
                    ) : (
                      <tr>
                        <th className={`${th} text-left`}>Mes</th>
                        <th className={th}>Estudios</th>
                        <th className={th}>Diferencia vs Promedio</th>
                        <th className={th}>Estudios Objetivo ({TARGET_UTILIZATION} %{basisLabel})</th>
                        <th className={th}>Diferencia vs Objetivo</th>
                      </tr>
                    )}
                  </thead>
                  <tbody className="divide-y divide-gray-100">
                    {rows.map(r => (
                      <tr key={r.mes} className={r.included ? '' : 'bg-gray-50 text-gray-400'}>
                        <td className={`${td} text-left font-bold`}>
                          {r.mes}
                          {!r.included && <span className="ml-2 text-[10px] font-bold uppercase text-gray-400">Fuera de la selección</span>}
                        </td>
                        {isUtil ? (
                          <>
                            <td className={td}>{formatHours(r.availHours)}</td>
                            <td className={td}>{formatHours(r.usedHours)}</td>
                            <td className={td}>
                              <span className="font-black" style={r.included ? { color: calc.utilizationColor(r.util) } : undefined}>{r.util.toFixed(1)}%</span>
                            </td>
                            <td className={td}>{formatCount(r.studies)}</td>
                          </>
                        ) : (
                          <>
                            <td className={`${td} font-bold`}>{formatCount(r.studies)}</td>
                            <td className={td}>{r.included ? `${r.studies - average >= 0 ? '+' : ''}${formatCount(r.studies - average)}` : '—'}</td>
                            <td className={td}>{r.targetStudies !== null ? formatCount(r.targetStudies) : '—'}</td>
                            <td className={td}>{r.targetStudies !== null && r.comparedStudies !== null ? formatSigned(r.comparedStudies - r.targetStudies) : '—'}</td>
                          </>
                        )}
                      </tr>
                    ))}
                    <tr className="bg-gray-100 border-t-2 border-gray-300 font-black text-gray-800">
                      {isUtil ? (
                        <>
                          <td className={`${td} text-left uppercase text-xs`}>Promedio anual</td>
                          <td className={td}>{formatHours(included.reduce((a, r) => a + r.availHours, 0))}</td>
                          <td className={td}>{formatHours(included.reduce((a, r) => a + r.usedHours, 0))}</td>
                          <td className={td}>
                            <span style={{ color: calc.utilizationColor(summary ? summary.util : 0) }}>{(summary ? summary.util : 0).toFixed(1)}%</span>
                          </td>
                          <td className={td}>{formatCount(included.reduce((a, r) => a + r.studies, 0))}</td>
                        </>
                      ) : (
                        <>
                          <td className={`${td} text-left uppercase text-xs`}>Total / promedio</td>
                          <td className={td}>{formatCount(included.reduce((a, r) => a + r.studies, 0))} · {formatCount(average)} por mes</td>
                          <td className={td}></td>
                          <td className={td}>{targetTotal !== null ? formatCount(targetTotal) : '—'}</td>
                          <td className={td}>{targetSummary && targetSummary.gap !== null ? formatSigned(targetSummary.gap) : '—'}</td>
                        </>
                      )}
                    </tr>
                  </tbody>
                </table>
              </div>
              <p className="mt-3 text-[11px] text-gray-400">
                {isUtil
                  ? 'El promedio anual es horas usadas sobre horas hábiles de los meses seleccionados (no el promedio simple de los porcentajes mensuales).'
                  : `El promedio es la suma de estudios de los meses seleccionados dividida por la cantidad de esos meses. El objetivo de cada mes son los estudios que cabrían en el ${TARGET_UTILIZATION} % de ${targetSummary && targetSummary.basis === 'agenda' ? 'las horas de agenda abierta del mes (solo cuentan los equipos y meses con agenda cargada)' : 'las horas hábiles del mes'} al tiempo promedio por estudio de la mezcla de los meses seleccionados (en la flota, suma de los objetivos de cada equipo). Barras azules: realizados; celestes: objetivo.`}
                {' '}Los meses en gris están fuera de la selección y no cuentan.
              </p>
            </>
          )}
        </div>
      </div>
    </div>
  );
};
