import React from "react";
import { ChevronDown, SlidersHorizontal, ChevronRight } from "lucide-react";
import { useModel } from "../model/ModelContext";

export const SimDistributionMatrix: React.FC = () => {
  const { data, disabledEqs, distributionInputs, expandedNodes, toggleNode, simulationHierarchy, updateDistribution, getEffectiveAllocation, getNodeLoad, healthyStats } = useModel();

  return (
    <>
      <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden mb-6">
        <div className="bg-gray-800 p-5">
           <h3 className="text-lg font-bold text-white flex items-center gap-2">
              <SlidersHorizontal size={20} className="text-orange-400"/> Matriz de Distribución Jerárquica
           </h3>
           <p className="text-xs text-gray-400 mt-1">Asigna los porcentajes de derivación. La columna "Asignado" te alertará si superas o no alcanzas el 100%.</p>
        </div>

        <div className="overflow-x-auto max-h-[600px] custom-scrollbar">
           <table className="w-full text-sm text-left">
             <thead className="bg-gray-50 uppercase sticky top-0 z-20 shadow-sm">
               <tr>
                 <th className="px-4 py-3 font-bold text-gray-600 text-[10px] sticky left-0 bg-gray-50 border-r border-b border-gray-200 z-30 w-[300px]">Jerarquía de Estudio</th>
                 <th className="px-4 py-3 text-center font-bold text-orange-600 text-[10px] border-b border-gray-200 border-r w-[80px]">Volumen</th>

                 <th className="px-4 py-3 text-center font-bold text-gray-500 text-[10px] border-b border-gray-200 border-r w-[90px] bg-gray-100/50">Asignado</th>

                 {data.equipments.filter(eq => !disabledEqs.includes(eq)).map(eq => {
                    const st = healthyStats[eq];
                    return (
                     <th key={eq} className="px-4 py-2 border-b border-gray-200 align-top min-w-[140px]">
                       <div className="flex items-center justify-between gap-2 mb-2">
                          <span className="font-black text-gray-800 text-[11px] truncate" title={eq}>{eq}</span>
                       </div>
                       <div className="flex flex-col gap-1 text-[9px]">
                          <div className="flex justify-between text-gray-500"><span>Util. Base:</span> <span className="font-bold">{st.baseUtil.toFixed(1)}%</span></div>
                          <div className="flex justify-between font-bold text-gray-800">
                             <span>Simulada:</span> 
                             <span className={st.simUtil > 100 ? 'text-red-600' : 'text-emerald-600'}>{st.simUtil.toFixed(1)}%</span>
                          </div>
                       </div>
                     </th>
                   );
                 })}
               </tr>
             </thead>
             <tbody className="divide-y divide-gray-100">
               {Object.keys(simulationHierarchy).sort().map(p => {
                   const pLoad = getNodeLoad('P', p);
                   if (pLoad === 0) return null;
                   const pKey = `P:${p}`;
                   const isPExpanded = expandedNodes.has(pKey);

                   const totalAllocatedP = getEffectiveAllocation('P', p);
                   const allocColorP = Math.abs(totalAllocatedP - 100) < 0.1 ? 'text-emerald-600' : totalAllocatedP > 100 ? 'text-red-600' : 'text-orange-500';
                   const barColorP = Math.abs(totalAllocatedP - 100) < 0.1 ? 'bg-emerald-500' : totalAllocatedP > 100 ? 'bg-red-500' : 'bg-orange-400';

                   return (
                     <React.Fragment key={pKey}>
                        <tr className="bg-gray-50/50 hover:bg-gray-100 transition-colors">
                           <td className="px-2 py-2 sticky left-0 bg-gray-50/90 border-r shadow-[2px_0_5px_-2px_rgba(0,0,0,0.05)] z-10">
                              <div className="flex items-center gap-2">
                                 <button onClick={() => toggleNode(pKey)} className="p-1 hover:bg-gray-200 rounded text-gray-500 shrink-0">
                                    {isPExpanded ? <ChevronDown size={14}/> : <ChevronRight size={14}/>}
                                 </button>
                                 <span className="font-bold text-gray-800 text-[11px] uppercase truncate">{p}</span>
                              </div>
                           </td>
                           <td className="px-4 py-2 text-center font-black text-orange-600 text-[11px] border-r bg-orange-50/30">{pLoad}</td>

                           <td className="px-2 py-1.5 border-r bg-gray-100/30">
                              <div className="flex flex-col items-center justify-center">
                                 <span className={`font-black text-[10px] ${allocColorP}`}>{totalAllocatedP.toFixed(1)}%</span>
                                 <div className="w-full h-1 bg-gray-200 rounded mt-1 overflow-hidden">
                                    <div className={`h-full ${barColorP}`} style={{ width: `${Math.min(totalAllocatedP, 100)}%` }}></div>
                                 </div>
                              </div>
                           </td>

                           {data.equipments.filter(eq => !disabledEqs.includes(eq)).map(eq => (
                              <td key={eq} className="px-4 py-1.5 text-center">
                                 <div className="flex items-center justify-center">
                                    <input 
                                       type="number" min="0" max="100" placeholder="-" 
                                       value={distributionInputs[pKey]?.[eq] !== undefined ? distributionInputs[pKey][eq] : ''}
                                       onChange={e => updateDistribution(pKey, eq, e.target.value)}
                                       className="w-16 text-center font-bold text-xs p-1 border border-gray-300 rounded focus:border-orange-500 focus:ring-1 outline-none"
                                    />
                                    <span className="text-[10px] text-gray-400 font-bold ml-1">%</span>
                                 </div>
                              </td>
                           ))}
                        </tr>

                        {isPExpanded && Object.keys(simulationHierarchy[p]).sort().map(s => {
                           const sLoad = getNodeLoad('S', p, s);
                           if (sLoad === 0) return null;
                           const sKey = `S:${p}|${s}`;
                           const isSExpanded = expandedNodes.has(sKey);

                           const totalAllocatedS = getEffectiveAllocation('S', p, s);
                           const allocColorS = Math.abs(totalAllocatedS - 100) < 0.1 ? 'text-emerald-600' : totalAllocatedS > 100 ? 'text-red-600' : 'text-gray-400';
                           const barColorS = Math.abs(totalAllocatedS - 100) < 0.1 ? 'bg-emerald-400' : totalAllocatedS > 100 ? 'bg-red-400' : 'bg-gray-300';

                           return (
                              <React.Fragment key={sKey}>
                                 <tr className="hover:bg-gray-50 transition-colors">
                                    <td className="px-2 py-1.5 sticky left-0 bg-white border-r z-10 pl-8">
                                       <div className="flex items-center gap-2">
                                          <button onClick={() => toggleNode(sKey)} className="p-0.5 hover:bg-gray-100 rounded text-gray-400 shrink-0">
                                             {isSExpanded ? <ChevronDown size={12}/> : <ChevronRight size={12}/>}
                                          </button>
                                          <span className="font-semibold text-gray-700 text-[11px] truncate">{s}</span>
                                       </div>
                                    </td>
                                    <td className="px-4 py-1.5 text-center font-bold text-orange-500 text-[11px] border-r">{sLoad}</td>

                                    <td className="px-2 py-1 border-r bg-gray-50/50">
                                       <div className="flex flex-col items-center justify-center">
                                          <span className={`font-bold text-[9px] ${allocColorS}`}>{totalAllocatedS.toFixed(1)}%</span>
                                          <div className="w-3/4 h-0.5 bg-gray-200 rounded mt-0.5 overflow-hidden">
                                             <div className={`h-full ${barColorS}`} style={{ width: `${Math.min(totalAllocatedS, 100)}%` }}></div>
                                          </div>
                                       </div>
                                    </td>

                                    {data.equipments.filter(eq => !disabledEqs.includes(eq)).map(eq => (
                                       <td key={eq} className="px-4 py-1.5 text-center">
                                          <div className="flex items-center justify-center">
                                             <input 
                                                type="number" min="0" max="100" placeholder="-" 
                                                value={distributionInputs[sKey]?.[eq] !== undefined ? distributionInputs[sKey][eq] : ''}
                                                onChange={e => updateDistribution(sKey, eq, e.target.value)}
                                                className="w-14 text-center font-bold text-xs p-1 border border-gray-200 rounded focus:border-orange-500 focus:ring-1 outline-none bg-gray-50"
                                             />
                                          </div>
                                       </td>
                                    ))}
                                 </tr>

                                 {isSExpanded && simulationHierarchy[p][s].sort().map(eStr => {
                                    const eLoad = getNodeLoad('E', p, s, eStr);
                                    if (eLoad === 0) return null;
                                    const eKey = `E:${eStr}`;

                                    const totalAllocatedE = getEffectiveAllocation('E', p, s, eStr);
                                    const allocColorE = Math.abs(totalAllocatedE - 100) < 0.1 ? 'text-emerald-500' : totalAllocatedE > 100 ? 'text-red-500' : 'text-gray-400';

                                    return (
                                       <tr key={eKey} className="hover:bg-orange-50/20 transition-colors">
                                          <td className="px-2 py-1.5 sticky left-0 bg-white border-r z-10 pl-14">
                                             <div className="flex items-center gap-2">
                                                <div className="w-1 h-1 rounded-full bg-gray-300 shrink-0"></div>
                                                <span className="text-gray-500 text-[10px] truncate" title={eStr}>{eStr}</span>
                                             </div>
                                          </td>
                                          <td className="px-4 py-1.5 text-center font-bold text-orange-400 text-[10px] border-r">{eLoad}</td>

                                          <td className="px-2 py-1 border-r bg-gray-50/20 text-center">
                                             <span className={`font-semibold text-[9px] ${allocColorE}`}>{totalAllocatedE.toFixed(1)}%</span>
                                          </td>

                                          {data.equipments.filter(eq => !disabledEqs.includes(eq)).map(eq => (
                                             <td key={eq} className="px-4 py-1 text-center">
                                                <div className="flex items-center justify-center">
                                                   <input 
                                                      type="number" min="0" max="100" placeholder="-" 
                                                      value={distributionInputs[eKey]?.[eq] !== undefined ? distributionInputs[eKey][eq] : ''}
                                                      onChange={e => updateDistribution(eKey, eq, e.target.value)}
                                                      className="w-12 text-center text-[10px] p-0.5 border-b border-transparent hover:border-gray-300 focus:border-orange-500 outline-none text-gray-700 font-bold"
                                                   />
                                                </div>
                                             </td>
                                          ))}
                                       </tr>
                                    );
                                 })}
                              </React.Fragment>
                           );
                        })}
                     </React.Fragment>
                   );
               })}
             </tbody>
           </table>
        </div>
      </div>
    </>
  );
};
