import React from "react";
import { Settings, ChevronDown, ChevronUp } from "lucide-react";
import { MONTH_NAMES } from "../config";
import { useModel } from "../model/ModelContext";

/** Panel de filtros: el año siempre; el equipo, la agrupación y los meses de la vista 1 sólo donde se usan. */
export const GlobalFilters: React.FC<{ showEquipment?: boolean; showGrouping?: boolean; showMonths?: boolean }> = ({ showEquipment = false, showGrouping = false, showMonths = false }) => {
  const { data, isGlobalFilterOpen, setIsGlobalFilterOpen, selectedEquipment, setSelectedEquipment, selectedYear, setSelectedYear, groupingLevel, setGroupingLevel, selectedStudyType, setSelectedStudyType, availableCategories, excludedMonthsFleet, fleetMonthsWithData, toggleMonthFleet, resetMonthsFleet } = useModel();

  return (
    <>
      {/* PANEL DE FILTROS GLOBALES DESTACADO Y COLAPSABLE */}
      <div className="bg-white rounded-2xl shadow-md border border-blue-200 overflow-hidden sticky top-4 z-50 mb-6 print:hidden">
        <div 
          className={`p-4 px-5 flex justify-between items-center bg-blue-50/50 cursor-pointer select-none transition-colors hover:bg-blue-50 ${isGlobalFilterOpen ? 'border-b border-blue-100' : ''}`}
          onClick={() => setIsGlobalFilterOpen(!isGlobalFilterOpen)}
        >
          <div className="flex items-center gap-2">
             <Settings size={18} className="text-blue-700"/>
             <span className="text-sm font-black text-blue-900">Filtros Globales y Configuración</span>
          </div>
          <button className="p-1 rounded-full hover:bg-blue-100 transition-colors text-blue-600">
             {isGlobalFilterOpen ? <ChevronUp size={18}/> : <ChevronDown size={18}/>}
          </button>
        </div>

        {isGlobalFilterOpen && (
          <div className="p-5 flex flex-wrap items-end justify-between gap-6 bg-white">
            <div className="flex flex-wrap gap-4 items-end">
              {showEquipment && (
                <div>
                  <label className="block text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-1">Equipo Principal</label>
                  <select value={selectedEquipment} onChange={e => setSelectedEquipment(e.target.value)} className="w-56 bg-gray-50 border border-gray-300 text-sm rounded-lg p-2 font-bold outline-none focus:ring-2 focus:ring-blue-500">
                    {data.equipments.map(eq => <option key={eq} value={eq}>{eq}</option>)}
                  </select>
                </div>
              )}
              <div>
                <label className="block text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-1">Año</label>
                <select value={selectedYear} onChange={e => setSelectedYear(parseInt(e.target.value))} className="w-24 bg-gray-50 border border-gray-300 text-sm rounded-lg p-2 font-bold outline-none focus:ring-2 focus:ring-blue-500">
                  {data.years.map(yr => <option key={yr} value={yr}>{yr}</option>)}
                </select>
              </div>
              {showMonths && (
                <div className="pl-4 border-l border-gray-200">
                  <div className="flex items-center gap-3 mb-1">
                    <label className="block text-[10px] font-bold text-gray-500 uppercase tracking-wider">Meses considerados</label>
                    <button onClick={resetMonthsFleet} className="text-[10px] font-bold text-blue-600 hover:underline">Todos los meses con datos</button>
                  </div>
                  <div className="flex gap-1 flex-wrap">
                    {MONTH_NAMES.map(m => {
                      const hasData = fleetMonthsWithData.has(m);
                      const selected = hasData && !excludedMonthsFleet.has(m);
                      return (
                        <button
                          key={m}
                          onClick={() => toggleMonthFleet(m)}
                          disabled={!hasData}
                          title={hasData ? m : `${m}: sin datos`}
                          className={`px-2 py-1 text-[10px] font-bold rounded border transition-colors ${!hasData ? 'bg-gray-100 text-gray-300 border-gray-100 opacity-50 cursor-not-allowed' : (selected ? 'bg-blue-100 text-blue-800 border-blue-300 shadow-sm' : 'bg-white text-gray-400 border-gray-200 hover:bg-gray-100')}`}
                        >{m.substring(0, 3)}</button>
                      );
                    })}
                  </div>
                </div>
              )}
              {showGrouping && (
                <>
                  <div className="pl-4 border-l border-gray-200">
                    <label className="block text-[10px] font-bold text-purple-600 uppercase tracking-wider mb-1">Nivel de Agrupación</label>
                    <select value={groupingLevel} onChange={e => setGroupingLevel(e.target.value as any)} className="w-48 bg-purple-50 border border-purple-200 text-purple-900 text-sm rounded-lg p-2 font-bold outline-none focus:ring-2 focus:ring-purple-500">
                      <option value="principal">Categoría Principal</option>
                      <option value="secundaria">Categoría Secundaria</option>
                      <option value="estudio">Nombre del Estudio</option>
                      <option value="todo">Total (Todos los estudios)</option>
                    </select>
                  </div>
                  <div className="pl-4 border-l border-gray-200">
                    <label className="block text-[10px] font-bold text-emerald-600 uppercase tracking-wider mb-1">
                      {groupingLevel === 'principal' ? 'Categoría Principal' : groupingLevel === 'secundaria' ? 'Categoría Secundaria' : groupingLevel === 'todo' ? 'General' : 'Estudio'}
                    </label>
                    <select value={selectedStudyType} onChange={e => setSelectedStudyType(e.target.value)} className="w-48 bg-emerald-50 border border-emerald-200 text-emerald-900 text-sm rounded-lg p-2 font-bold outline-none focus:ring-2 focus:ring-emerald-500">
                      {availableCategories.map(st => <option key={st} value={st}>{st}</option>)}
                    </select>
                  </div>
                </>
              )}
            </div>
          </div>
        )}
      </div>
    </>
  );
};
