import { Dataset } from "../data/types";
import { TARGET_UTILIZATION } from "../config";
import { addCategories, CategoryHours, emptyCategories, equipmentMonthLoad, fleetMonthlyDetail } from "./fleet";
import type { ExtraLoad } from "./matrix";
import { CustomTimes } from "./times";

// Capacidad de agenda: de las horas en que la clínica estuvo abierta (potencial, horas hábiles),
// cuántas tuvo la agenda del equipo abierta para agendar, y cuántas se usaron en adquirir estudios.
//   Cobertura de agenda            = horas de agenda / horas potenciales
//   Utilización efectiva de agenda = horas de adquisición / horas de agenda
//   (cobertura × utilización efectiva = horas de adquisición / horas potenciales)
// La agenda de un mes se limita a las horas hábiles de ese mes. Un mes sin dato de agenda para un
// equipo queda fuera de TODOS sus indicadores de agenda (también del potencial y de la adquisición),
// para que las tres cifras sean comparables.

export type AgendaSource = Pick<Dataset, "times" | "monthlyQuantities" | "studyHierarchy" | "hours" | "hoursByEquipment" | "maxMonthPerYear" | "agenda">;

/** Horas de agenda abierta tal como las informa la hoja (sin tope), o undefined si no hay dato. */
export const rawAgendaHours = (ds: Pick<Dataset, "agenda">, eq: string, year: number, mes: string): number | undefined =>
  ds.agenda && ds.agenda[eq] && ds.agenda[eq][year] ? ds.agenda[eq][year][mes] : undefined;

export interface AgendaStat {
  label: string;
  /** Horas hábiles (clínica abierta) de los meses con agenda cargada. */
  potentialHours: number;
  /** Horas de agenda abierta, limitadas a las horas hábiles de cada mes. */
  agendaHours: number;
  /** Horas de adquisición de estudios de esos mismos meses. */
  usedHours: number;
  /** Meses considerados (seleccionados y con agenda cargada). */
  months: number;
  /** Meses en que la agenda informada superaba las horas hábiles y se limitó. */
  cappedMonths: number;
  /** agenda / potencial (%), o null si no hay datos. */
  coverage: number | null;
  /** adquisición / agenda (%), o null si no hay datos. */
  effective: number | null;
  /** Estudios de esos mismos meses (con agenda cargada). */
  studies: number;
  /** Horas de adquisición y estudios de esos meses por categoría principal. */
  hoursByCategory: CategoryHours;
  studiesByCategory: CategoryHours;
  /**
   * Estudios que corresponden al objetivo de utilización sobre la agenda abierta, con la mezcla de
   * estudios del período: los realizados escalados de la utilización efectiva al objetivo. En un
   * consolidado es la suma de los objetivos de cada equipo. null si no hubo estudios en esos meses.
   */
  targetStudies: number | null;
  /** Estudios realizados menos estudios objetivo (negativo = faltan estudios). */
  studyGap: number | null;
}

const EPS = 1e-9;

type StatBase = Omit<AgendaStat, "coverage" | "effective" | "targetStudies" | "studyGap">;

const finish = (s: StatBase, targetOverride?: number | null): AgendaStat => {
  const effective = s.months > 0 && s.agendaHours > 0 ? (s.usedHours / s.agendaHours) * 100 : null;
  const ownTarget = effective !== null && effective > 0 && s.studies > 0 ? (s.studies * TARGET_UTILIZATION) / effective : null;
  const target = targetOverride !== undefined ? targetOverride : ownTarget;
  return {
    ...s,
    coverage: s.months > 0 && s.potentialHours > 0 ? (s.agendaHours / s.potentialHours) * 100 : null,
    effective,
    targetStudies: target,
    studyGap: target === null ? null : s.studies - target,
  };
};

/** Suma varios equipos (consolidado): los porcentajes salen de las horas sumadas, no de promediar porcentajes. */
export const sumAgenda = (label: string, stats: AgendaStat[]): AgendaStat =>
  finish({
    label,
    potentialHours: stats.reduce((a, s) => a + s.potentialHours, 0),
    agendaHours: stats.reduce((a, s) => a + s.agendaHours, 0),
    usedHours: stats.reduce((a, s) => a + s.usedHours, 0),
    months: stats.reduce((a, s) => a + s.months, 0),
    cappedMonths: stats.reduce((a, s) => a + s.cappedMonths, 0),
    studies: stats.reduce((a, s) => a + s.studies, 0),
    hoursByCategory: stats.reduce((a, s) => addCategories(a, s.hoursByCategory), emptyCategories()),
    studiesByCategory: stats.reduce((a, s) => addCategories(a, s.studiesByCategory), emptyCategories()),
  }, stats.some((s) => s.targetStudies !== null) ? stats.reduce((a, s) => a + (s.targetStudies || 0), 0) : null);

/**
 * Indicadores de agenda de un equipo en los meses no excluidos de un año.
 * `extra` es la carga reubicada por el simulador: suma horas de adquisición al equipo receptor y
 * deja igual su agenda y sus horas hábiles (la agenda abierta no cambia por simular).
 */
export const equipmentAgendaStat = (
  ds: AgendaSource & Pick<Dataset, "hours" | "hoursByEquipment">,
  custom: CustomTimes,
  p: { year: number; excluded: Set<string>; eq: string; extra?: ExtraLoad }
): AgendaStat => {
  const months = fleetMonthlyDetail(ds, custom, { year: p.year, excluded: p.excluded, equipments: [p.eq], extra: p.extra });
  let potential = 0;
  let agenda = 0;
  let used = 0;
  let studies = 0;
  let hoursByCategory = emptyCategories();
  let studiesByCategory = emptyCategories();
  let n = 0;
  let capped = 0;
  months.forEach((d) => {
    if (!d.included || !d.hasData) return;
    const raw = rawAgendaHours(ds, p.eq, p.year, d.mes);
    if (raw === undefined) return;
    n++;
    potential += d.availHours;
    used += d.usedHours;
    studies += d.studies;
    const load = equipmentMonthLoad(ds, custom, p.eq, p.year, d.mes, p.extra);
    hoursByCategory = addCategories(hoursByCategory, load.hours);
    studiesByCategory = addCategories(studiesByCategory, load.studies);
    if (raw > d.availHours + EPS) capped++;
    agenda += Math.min(raw, d.availHours);
  });
  return finish({
    label: p.eq, potentialHours: potential, agendaHours: agenda, usedHours: used, months: n, cappedMonths: capped,
    studies, hoursByCategory, studiesByCategory,
  });
};

export interface AgendaSummary {
  /** Un registro por equipo, en el orden de `equipments`. */
  rows: AgendaStat[];
  /** Consolidado de los equipos activos. */
  total: AgendaStat;
}

export const agendaSummary = (
  ds: AgendaSource,
  custom: CustomTimes,
  p: { year: number; excluded: Set<string>; equipments: string[]; activeEqs: Set<string>; extra?: ExtraLoad }
): AgendaSummary => {
  const rows = p.equipments.map((eq) => equipmentAgendaStat(ds, custom, { year: p.year, excluded: p.excluded, eq, extra: p.extra }));
  return { rows, total: sumAgenda("Total flota activa", rows.filter((r) => p.activeEqs.has(r.label))) };
};

export interface AgendaChartData {
  /** Grupos de tres barras: primero el consolidado (si hay más de un equipo) y después cada equipo. */
  groups: AgendaStat[];
  /** Equipos elegidos que no tienen agenda cargada en los meses considerados. */
  withoutData: string[];
}

/** Arma lo que muestra el gráfico para un conjunto de equipos elegidos (uno, varios o todos). */
export const agendaChartData = (summary: AgendaSummary, selected: string[], showDetail: boolean): AgendaChartData => {
  const chosen = summary.rows.filter((r) => selected.indexOf(r.label) !== -1);
  const withData = chosen.filter((r) => r.months > 0);
  const withoutData = chosen.filter((r) => r.months === 0).map((r) => r.label);
  if (withData.length === 0) return { groups: [], withoutData };
  if (withData.length === 1) return { groups: [withData[0]], withoutData };
  const consolidated = sumAgenda(`Consolidado (${withData.length} equipos)`, withData);
  return { groups: showDetail ? [consolidated].concat(withData) : [consolidated], withoutData };
};
